use crate::app::{Feishin, LeaveFullPlayer, NextTrack, Route, ToggleFullScreenPlayer, TogglePlay};
use feishin_core::{
    model::{ArtistInfo, ArtistTab, Item, ItemKind},
    queue::Enqueue,
    storage::State,
};
use gpui::{AppContext, KeyBinding, TestAppContext};
use gpui_component::Root;
use std::{cell::RefCell, rc::Rc};

fn fixture_state() -> State {
    let mut state = State::default();
    state.settings.confirm_large_fetch = false;
    state
}

#[gpui::test]
fn default_album_cards_show_artist_credits_and_honor_saved_rows(cx: &mut TestAppContext) {
    use gpui::{Modifiers, accesskit::Role, point, px, size};
    cx.use_platform_text_system();
    cx.set_assets(crate::icons::Assets);
    cx.update(|cx| {
        gpui_component::init(cx);
        crate::fonts::register_builtins(cx).unwrap();
    });
    let dir = std::env::temp_dir().join(format!("feishin-default-cards-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        window.activate_accessibility_for_test();
        let mut state = fixture_state();
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        state.settings.sidebar.playlist_list = false;
        let app = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(app.clone()));
        Root::new(app, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.simulate_resize(size(px(1320.), px(840.)));
    cx.run_until_parked();
    let album = Item {
        kind: ItemKind::Album,
        id: "album".into(),
        name: "Fixture Album".into(),
        album_artist: "Fixture Artist".into(),
        album_artist_links: Some(vec![("artist".into(), "Fixture Artist".into())]),
        // Albums need not include track-artist identities.
        artist_links: Some(vec![]),
        ..Default::default()
    };
    app.update(cx, |view, cx| {
        view.route = Route::Library(ItemKind::Album);
        view.items = vec![album.clone()];
        view.state.queue.add(
            vec![Item {
                id: "retained".into(),
                ..Default::default()
            }],
            Enqueue::Now,
        );
        cx.notify();
    });
    cx.run_until_parked();
    let queue = app.read_with(cx, |view, _| {
        serde_json::to_value(&view.state.queue).unwrap()
    });
    cx.executor()
        .advance_clock(std::time::Duration::from_millis(600));
    cx.refresh().unwrap();
    cx.run_until_parked();
    let credit_bounds = cx.debug_bounds("card-metadata-0-1").unwrap();
    let painted = cx.update(|window, _| {
        window
            .painted_glyphs_for_test()
            .into_iter()
            .filter(|(bounds, mask, _)| {
                credit_bounds.contains(&bounds.center()) && mask.contains(&bounds.center())
            })
            .count()
    });
    assert!(
        painted >= 10,
        "Artist credits must paint their text, not just an ellipsis: {painted} glyphs in {credit_bounds:?}"
    );
    let artist_point = cx.update(|window, _| {
        let scale = window.scale_factor() as f64;
        let tree = window.accessibility_tree_for_test().unwrap();
        let node = tree
            .nodes
            .iter()
            .find(|(_, node)| node.role() == Role::Link && node.label() == Some("Fixture Artist"))
            .expect("default album cards must show album artists");
        let bounds = node.1.bounds().unwrap();
        point(
            px(((bounds.x0 + bounds.x1) / (2. * scale)) as f32),
            px(((bounds.y0 + bounds.y1) / (2. * scale)) as f32),
        )
    });
    cx.simulate_click(artist_point, Modifiers::none());
    cx.run_until_parked();
    app.read_with(cx, |view, _| {
        assert!(matches!(&view.route, Route::Detail(item) if item.id == "artist" && item.kind == ItemKind::AlbumArtist));
        assert_eq!(serde_json::to_value(&view.state.queue).unwrap(), queue);
    });
    app.update(cx, |view, cx| {
        view.route = Route::Library(ItemKind::Album);
        view.items = vec![album.clone()];
        let mut config = feishin_core::lists::default_for("album");
        config.grid.rows.retain(|row| row.id == "name");
        view.state.settings.lists.insert("album".into(), config);
        cx.notify();
    });
    cx.run_until_parked();
    cx.update(|window, _| {
        assert!(
            !window
                .accessibility_tree_for_test()
                .unwrap()
                .nodes
                .iter()
                .any(
                    |(_, node)| node.role() == Role::Link && node.label() == Some("Fixture Artist")
                )
        )
    });
    for keyboard in [true, false] {
        app.update(cx, |view, cx| {
            view.route = Route::Library(ItemKind::Album);
            view.items = vec![album.clone()];
            view.state.settings.enable_grid_multiselect = true;
            cx.notify();
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            use gpui::accesskit::{Action, ActionRequest, TreeId};
            let tree = window.accessibility_tree_for_test().unwrap();
            let (id, _) = tree
                .nodes
                .iter()
                .find(|(_, node)| {
                    node.role() == Role::Link && node.label() == Some("Fixture Album")
                })
                .expect("Album titles must remain accessible navigation links");
            window.dispatch_accessibility_action_for_test(
                ActionRequest {
                    action: if keyboard {
                        Action::Focus
                    } else {
                        Action::Click
                    },
                    target_tree: TreeId::ROOT,
                    target_node: *id,
                    data: None,
                },
                cx,
            );
        });
        cx.run_until_parked();
        if keyboard {
            cx.simulate_keystrokes("enter");
            cx.run_until_parked();
        }
        app.read_with(cx, |view, _| {
            assert!(matches!(&view.route, Route::Detail(item) if item.id == "album" && item.kind == ItemKind::Album));
            assert_eq!(serde_json::to_value(&view.state.queue).unwrap(), queue);
        });
    }
    std::fs::remove_dir_all(dir).ok();
}

#[gpui::test]
fn settings_search_expands_clears_and_restores_focus(cx: &mut TestAppContext) {
    use gpui::{Focusable, Modifiers, VisualTestContext, px};
    cx.set_assets(crate::icons::Assets);
    cx.update(gpui_component::init);
    let dir =
        std::env::temp_dir().join(format!("feishin-settings-search-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        window.activate_window();
        let app = cx.new(|cx| Feishin::new(dir.clone(), Ok(fixture_state()), window, cx));
        app.update(cx, |view, _| view.route = Route::Settings);
        captured.replace(Some(app.clone()));
        Root::new(app, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.simulate_resize(gpui::size(px(1400.), px(1000.)));
    let settle = |cx: &mut VisualTestContext| {
        // Blur is delivered after paint, then starts the shared CSS transition.
        for _ in 0..2 {
            cx.run_until_parked();
            cx.executor()
                .advance_clock(std::time::Duration::from_millis(350));
        }
        cx.run_until_parked();
    };
    let click = |selector: &str, cx: &mut VisualTestContext| {
        let point = cx.debug_bounds(selector).unwrap().center();
        cx.simulate_click(point, Modifiers::none());
        settle(cx);
    };
    let width =
        |cx: &mut VisualTestContext| cx.debug_bounds("settings-search-input").unwrap().size.width;
    settle(cx);
    assert_eq!(width(cx), px(36.));
    click("settings-search-open", cx);
    assert_eq!(width(cx), px(200.));
    assert!(cx.update(|window, cx| {
        app.read(cx)
            .settings_search
            .read(cx)
            .focus_handle(cx)
            .is_focused(window)
    }));
    cx.simulate_input("Language");
    settle(cx);
    click("settings-tab-playback", cx);
    assert_eq!(width(cx), px(200.));
    assert_eq!(
        app.read_with(cx, |view, cx| view
            .settings_search
            .read(cx)
            .value()
            .to_string()),
        "Language"
    );
    click("settings-search-clear", cx);
    assert!(
        app.read_with(cx, |view, cx| view
            .settings_search
            .read(cx)
            .value()
            .is_empty()),
        "Clear must empty the settings query"
    );
    assert_eq!(width(cx), px(200.));
    assert!(cx.update(|window, cx| {
        app.read(cx)
            .settings_search
            .read(cx)
            .focus_handle(cx)
            .is_focused(window)
    }));
    click("settings-tab-general", cx);
    assert!(
        cx.update(|window, cx| app.read(cx).settings_tab_focus[0].is_focused(window)),
        "Clicking a settings tab must focus it"
    );
    assert!(
        !app.read_with(cx, |view, _| view.settings_search_open),
        "Empty search must close on blur"
    );
    assert_eq!(width(cx), px(36.));
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            view.run_shortcut(feishin_core::shortcuts::Action::LocalSearch, window, cx)
        })
    });
    settle(cx);
    assert_eq!(width(cx), px(200.));
    cx.simulate_input("Language");
    settle(cx);
    click("settings-tab-playback", cx);
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            view.run_shortcut(feishin_core::shortcuts::Action::LocalSearch, window, cx)
        })
    });
    settle(cx);
    cx.simulate_input("volume");
    settle(cx);
    assert_eq!(
        app.read_with(cx, |view, cx| view
            .settings_search
            .read(cx)
            .value()
            .to_string()),
        "volume"
    );
    cx.simulate_keystrokes("escape");
    settle(cx);
    assert_eq!(width(cx), px(36.));
    assert!(app.read_with(cx, |view, cx| {
        view.settings_search.read(cx).value().is_empty()
    }));
    assert!(cx.update(|window, cx| app.read(cx).focus.is_focused(window)));
    let _ = std::fs::remove_dir_all(dir);
}

#[gpui::test]
fn settings_categories_search_keyboard_and_saved_selection(cx: &mut TestAppContext) {
    use feishin_core::settings_search::Tab;
    use gpui::{Modifiers, Role, px};
    cx.set_assets(crate::icons::Assets);
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!("feishin-settings-tabs-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        window.activate_accessibility_for_test();
        let app = cx.new(|cx| Feishin::new(dir.clone(), Ok(fixture_state()), window, cx));
        app.update(cx, |view, _| view.route = Route::Settings);
        captured.replace(Some(app.clone()));
        Root::new(app, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.simulate_resize(gpui::size(px(1400.), px(1000.)));
    // Debug bounds retain prior frame entries; the accessibility tree describes
    // the currently mounted controls after a category change.
    let visible = |cx: &mut gpui::VisualTestContext, selector: &str| {
        let (role, label) = match selector {
            "language" => (Role::Button, "Language: en".to_owned()),
            "native-tray" => (
                Role::CheckBox,
                feishin_core::i18n::text("en", "setting.trayEnabled"),
            ),
            "media-session" => (
                Role::CheckBox,
                feishin_core::i18n::text("en", "setting.mediaSession"),
            ),
            _ => unreachable!(),
        };
        cx.update(|window, _| {
            window
                .accessibility_tree_for_test()
                .unwrap()
                .nodes
                .iter()
                .any(|(_, node)| node.role() == role && node.label() == Some(label.as_str()))
        })
    };
    for (tab, present, absent) in [
        (Tab::General, "language", "native-tray"),
        (Tab::Playback, "settings-playback-config", "language"),
        (Tab::Hotkeys, "media-session", "native-tray"),
        (Tab::Window, "native-tray", "language"),
        (Tab::Advanced, "restart-native", "media-session"),
    ] {
        cx.run_until_parked();
        let target = cx
            .debug_bounds(&format!("settings-tab-{}", tab.id()))
            .unwrap()
            .center();
        cx.simulate_click(target, Modifiers::none());
        cx.run_until_parked();
        assert!(cx.debug_bounds(present).is_some(), "{tab:?}: {present}");
        assert!(!visible(cx, absent), "{tab:?}: {absent}");
        assert_eq!(
            feishin_core::storage::load(&dir.join("state.json"))
                .unwrap()
                .settings
                .settings_tab,
            tab
        );
        cx.update(|window, _| {
            let tree = window.accessibility_tree_for_test().unwrap();
            let tabs: Vec<_> = tree
                .nodes
                .iter()
                .filter(|(_, node)| node.role() == Role::Tab)
                .collect();
            assert_eq!(tabs.len(), 5);
            let selected: Vec<_> = tabs
                .into_iter()
                .filter(|(_, node)| node.is_selected() == Some(true))
                .collect();
            assert_eq!(selected.len(), 1);
            assert_eq!(
                selected[0].1.label(),
                Some(feishin_core::i18n::text("en", tab.title()).as_str())
            );
        });
    }
    // The original search filters the active category and survives tab changes.
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            view.settings_search
                .update(cx, |input, cx| input.set_value("Language", window, cx));
            view.settings_tab_focus[4].focus(window);
            cx.notify();
        })
    });
    cx.run_until_parked();
    assert!(!visible(cx, "language"));
    cx.simulate_keystrokes("home");
    cx.run_until_parked();
    assert!(visible(cx, "language"));
    assert!(!visible(cx, "native-tray"));
    cx.simulate_keystrokes("right");
    cx.run_until_parked();
    assert_eq!(
        app.read_with(cx, |view, _| view.state.settings.settings_tab),
        Tab::Playback
    );
    assert!(!visible(cx, "language"));
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            view.state.settings.language = "ar".into();
            view.settings_search
                .update(cx, |input, cx| input.set_value("", window, cx));
            view.apply_theme(window, cx);
            cx.notify();
        })
    });
    cx.run_until_parked();
    cx.simulate_keystrokes("left");
    cx.run_until_parked();
    assert_eq!(
        app.read_with(cx, |view, _| view.state.settings.settings_tab),
        Tab::Hotkeys
    );
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.navigate(Route::Home, cx);
            view.navigate(Route::Settings, cx);
        })
    });
    cx.run_until_parked();
    assert_eq!(
        app.read_with(cx, |view, _| view.state.settings.settings_tab),
        Tab::Hotkeys
    );
    let _ = std::fs::remove_dir_all(dir);
}

#[gpui::test]
fn artist_tables_share_columns_and_keep_selection_focus_and_displayed_playback(
    cx: &mut TestAppContext,
) {
    use feishin_core::{
        lists::{Column, Size},
        shortcuts::Action,
    };
    use gpui::{Modifiers, MouseButton, point, px};
    cx.set_assets(crate::icons::Assets);
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!("feishin-artist-table-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.sidebar.playlist_list = false;
        state.settings.artist_items = ["topSongs", "favoriteSongs"]
            .into_iter()
            .map(|id| feishin_core::releases::Setting {
                id: id.into(),
                disabled: false,
            })
            .collect();
        let mut config = feishin_core::lists::default_for("song");
        config.table.auto_fit_columns = false;
        config.table.columns = vec![
            Column {
                id: "name".into(),
                width: 280.,
                ..Default::default()
            },
            Column {
                id: "duration".into(),
                width: 80.,
                ..Default::default()
            },
        ];
        state.settings.lists.insert("song".into(), config);
        state.queue.add(
            vec![Item {
                id: "kept".into(),
                name: "Kept".into(),
                ..Default::default()
            }],
            Enqueue::Now,
        );
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.simulate_resize(gpui::size(px(1600.), px(1400.)));
    cx.run_until_parked();
    let songs = (0..20)
        .map(|index| Item {
            id: index.to_string(),
            name: format!("Song {index}"),
            duration: 100.,
            ..Default::default()
        })
        .collect::<Vec<_>>();
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.route = Route::Detail(Box::new(Item {
                id: "artist".into(),
                name: "Artist".into(),
                kind: ItemKind::AlbumArtist,
                ..Default::default()
            }));
            view.artist_overview = true;
            for id in ["topSongs", "favoriteSongs"] {
                view.artist_sections.insert(
                    id.into(),
                    crate::artist_overview::Section {
                        items: songs.clone(),
                        ..Default::default()
                    },
                );
            }
            cx.notify();
        })
    });
    let reference: serde_json::Value =
        serde_json::from_str(include_str!("../assets/artist-table-reference.json")).unwrap();
    for case in reference["heights"].as_array().unwrap() {
        let size: Size = serde_json::from_value(case["tableSize"].clone()).unwrap();
        cx.update(|_, cx| {
            app.update(cx, |view, cx| {
                let table = &mut view.state.settings.lists.get_mut("song").unwrap().table;
                table.size = size;
                table.enable_header = case["enableHeader"].as_bool().unwrap();
                let count = case["itemCount"].as_u64().unwrap() as usize;
                for section in view.artist_sections.values_mut() {
                    section.items = songs[..count].to_vec();
                }
                cx.notify();
            })
        });
        cx.run_until_parked();
        for id in ["topSongs", "favoriteSongs"] {
            let bounds = cx.debug_bounds(&format!("artist-table-{id}")).unwrap();
            assert!(
                (f64::from(f32::from(bounds.size.height)) - case["height"].as_f64().unwrap()).abs()
                    <= 1.,
                "{id}: {case}, {bounds:?}"
            );
        }
        let row = cx.debug_bounds("artist-section-song-topSongs-0").unwrap();
        assert!((f32::from(row.size.height) - size.row_height()).abs() <= 1.);
    }
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.state
                .settings
                .lists
                .get_mut("song")
                .unwrap()
                .table
                .size = Size::Compact;
            cx.notify();
        })
    });
    cx.run_until_parked();
    let click_row =
        |cx: &mut gpui::VisualTestContext, section: &str, index: usize, modifiers: Modifiers| {
            let center = cx
                .debug_bounds(&format!("artist-cell-{section}-{index}-name"))
                .unwrap()
                .center();
            cx.simulate_click(center, modifiers);
            cx.run_until_parked();
        };
    click_row(cx, "topSongs", 1, Modifiers::none());
    click_row(
        cx,
        "topSongs",
        3,
        Modifiers {
            shift: true,
            ..Default::default()
        },
    );
    app.read_with(cx, |view, _| {
        assert_eq!(
            view.artist_sections["topSongs"].selected,
            std::collections::HashSet::from(["1".into(), "2".into(), "3".into()])
        );
        assert!(view.artist_sections["favoriteSongs"].selected.is_empty());
        assert_eq!(view.state.queue.entries.len(), 1);
    });
    let select_all = if cfg!(target_os = "macos") {
        "cmd-a"
    } else {
        "ctrl-a"
    };
    cx.simulate_keystrokes(select_all);
    cx.run_until_parked();
    assert_eq!(
        app.read_with(cx, |view, _| view.artist_sections["topSongs"]
            .selected
            .len()),
        20
    );
    cx.simulate_keystrokes(select_all);
    cx.run_until_parked();
    assert!(app.read_with(cx, |view, _| {
        view.artist_sections["topSongs"].selected.is_empty()
    }));
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            view.artist_searches[0].update(cx, |input, cx| input.set_value("Song 1", window, cx));
            cx.notify();
        })
    });
    cx.run_until_parked();
    cx.executor()
        .advance_clock(std::time::Duration::from_millis(300));
    cx.run_until_parked();
    click_row(cx, "topSongs", 1, Modifiers::none());
    cx.simulate_keystrokes(select_all);
    cx.run_until_parked();
    let expected = std::iter::once("1".to_string())
        .chain((10..20).map(|index| index.to_string()))
        .chain(std::iter::once("0".to_string()))
        .chain((2..10).map(|index| index.to_string()))
        .collect::<Vec<_>>();
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            assert_eq!(
                view.artist_section_action_items("topSongs", 1, cx)
                    .iter()
                    .map(|item| item.id.clone())
                    .collect::<Vec<_>>(),
                expected
            );
            view.run_shortcut(Action::ListPlayNext, window, cx);
        })
    });
    cx.run_until_parked();
    app.read_with(cx, |view, _| {
        assert_eq!(
            view.state
                .queue
                .ordered()
                .iter()
                .skip(1)
                .map(|entry| entry.item.id.clone())
                .collect::<Vec<_>>(),
            vec!["1"]
        );
        assert!(!view.playing);
    });
    click_row(cx, "favoriteSongs", 0, Modifiers::none());
    cx.simulate_keystrokes(select_all);
    cx.run_until_parked();
    app.read_with(cx, |view, _| {
        assert_eq!(view.artist_sections["favoriteSongs"].selected.len(), 20);
        assert_eq!(view.artist_sections["topSongs"].selected.len(), 20);
    });
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.set_artist_favorite_sort(feishin_core::model::Sort::Random, false, cx);
            let order = view.artist_section_indices("favoriteSongs", cx);
            assert_eq!(order, view.artist_section_indices("favoriteSongs", cx));
            let mut members = order.clone();
            members.sort_unstable();
            assert_eq!(members, (0..20).collect::<Vec<_>>());
            assert_eq!(view.artist_sections["favoriteSongs"].selected.len(), 20);
            view.set_artist_favorite_sort(feishin_core::model::Sort::Id, false, cx);
            assert_eq!(view.artist_section_indices("favoriteSongs", cx), members);
        });
    });
    let last = cx
        .debug_bounds("artist-section-play-favoriteSongs-last")
        .unwrap()
        .center();
    cx.simulate_click(last, Modifiers::none());
    cx.run_until_parked();
    assert_eq!(
        app.read_with(cx, |view, _| view.state.queue.entries.len()),
        22
    );
    let resize = cx
        .debug_bounds("metadata-resize-duration")
        .unwrap()
        .center();
    cx.simulate_mouse_down(resize, MouseButton::Left, Modifiers::none());
    cx.simulate_mouse_move(
        point(resize.x + px(12.), resize.y),
        Some(MouseButton::Left),
        Modifiers::none(),
    );
    cx.simulate_mouse_move(
        point(resize.x + px(50.), resize.y),
        Some(MouseButton::Left),
        Modifiers::none(),
    );
    cx.simulate_mouse_up(
        point(resize.x + px(50.), resize.y),
        MouseButton::Left,
        Modifiers::none(),
    );
    cx.run_until_parked();
    app.read_with(cx, |view, _| {
        assert!(
            view.state.settings.lists["song"]
                .table
                .columns
                .iter()
                .find(|column| column.id == "duration")
                .unwrap()
                .width
                > 80.
        );
        assert_eq!(view.artist_sections["favoriteSongs"].selected.len(), 20);
    });
    let duration = cx
        .debug_bounds("metadata-header-duration")
        .unwrap()
        .center();
    let name = cx.debug_bounds("metadata-header-name").unwrap().center();
    cx.simulate_mouse_down(duration, MouseButton::Left, Modifiers::none());
    cx.simulate_mouse_move(
        duration + point(px(-12.), px(0.)),
        Some(MouseButton::Left),
        Modifiers::none(),
    );
    cx.simulate_mouse_move(name, Some(MouseButton::Left), Modifiers::none());
    cx.simulate_mouse_up(name, MouseButton::Left, Modifiers::none());
    cx.run_until_parked();
    assert_eq!(
        app.read_with(cx, |view, _| view.state.settings.lists["song"]
            .table
            .columns[0]
            .id
            .clone()),
        "duration"
    );
    let saved = feishin_core::storage::load(&dir.join("state.json")).unwrap();
    assert_eq!(saved.settings.lists["song"].table.columns[0].id, "duration");
    assert!(app.read_with(cx, |view, _| view.history.is_empty() && !view.playing));
    // Double-click always plays the displayed list, independent of the default play preference.
    cx.update(|_, cx| {
        app.update(cx, |view, _| {
            view.state.settings.play_button_behavior = feishin_core::queue::PlayBehavior::Next
        })
    });
    let center = cx
        .debug_bounds("artist-cell-topSongs-10-name")
        .unwrap()
        .center();
    cx.simulate_event(gpui::MouseDownEvent {
        position: center,
        button: MouseButton::Left,
        modifiers: Modifiers::none(),
        click_count: 2,
        first_mouse: false,
    });
    cx.simulate_event(gpui::MouseUpEvent {
        position: center,
        button: MouseButton::Left,
        modifiers: Modifiers::none(),
        click_count: 2,
    });
    cx.run_until_parked();
    assert!(cx.has_pending_prompt());
    assert_eq!(
        app.read_with(cx, |view, _| view
            .state
            .queue
            .current()
            .unwrap()
            .item
            .id
            .clone()),
        "kept"
    );
    cx.simulate_prompt_answer("Confirm");
    cx.run_until_parked();
    app.read_with(cx, |view, _| {
        assert_eq!(view.state.queue.current().unwrap().item.id, "10");
        assert_eq!(view.state.queue.entries.len(), 21);
        assert_eq!(view.state.queue.up_next.len(), 1);
        assert_eq!(view.state.queue.next_entry(false).unwrap().item.id, "1");
        assert_eq!(
            view.state.queue.next_entry(false).unwrap().key,
            view.state.queue.up_next[0]
        );
        assert!(!view.playing);
    });
    // Holding the section control enqueues one shuffled batch and suppresses release activation.
    let next = cx
        .debug_bounds("artist-section-play-favoriteSongs-next")
        .unwrap()
        .center();
    cx.simulate_mouse_down(next, MouseButton::Left, Modifiers::none());
    cx.run_until_parked();
    cx.executor()
        .advance_clock(std::time::Duration::from_millis(501));
    cx.run_until_parked();
    let length = app.read_with(cx, |view, _| view.state.queue.entries.len());
    assert_eq!(length, 41);
    cx.simulate_mouse_up(next, MouseButton::Left, Modifiers::none());
    cx.run_until_parked();
    assert_eq!(
        app.read_with(cx, |view, _| view.state.queue.entries.len()),
        length
    );
    // The original row artwork and focused-list shortcuts both play just one song.
    for case in reference["playback"].as_array().unwrap() {
        if case["kind"] == "doubleClick" {
            continue;
        }
        cx.update(|window, cx| {
            app.update(cx, |view, cx| {
                view.state.settings.confirm_queue_changes = false;
                view.state.settings.play_button_behavior = match case["mode"].as_str().unwrap() {
                    "next" => feishin_core::queue::PlayBehavior::Next,
                    "last" => feishin_core::queue::PlayBehavior::Last,
                    "shuffle" => feishin_core::queue::PlayBehavior::Shuffle,
                    _ => feishin_core::queue::PlayBehavior::Now,
                };
                view.state.queue = Default::default();
                view.artist_sections.remove("favoriteSongs");
                view.state
                    .settings
                    .artist_items
                    .retain(|section| section.id == "topSongs");
                let section = view.artist_sections.get_mut("topSongs").unwrap();
                section.items = songs[..3].to_vec();
                section.selected = std::collections::HashSet::from(["1".into()]);
                section.selection_order = vec!["1".into()];
                view.artist_searches[0].update(cx, |input, cx| input.set_value("", window, cx));
                view.state
                    .settings
                    .lists
                    .get_mut("song")
                    .unwrap()
                    .table
                    .columns = vec![Column {
                    id: "titleCombined".into(),
                    width: 400.,
                    ..Default::default()
                }];
                view.artist_song_focus[0].focus(window);
                cx.notify();
            });
        });
        cx.run_until_parked();
        cx.executor()
            .advance_clock(std::time::Duration::from_millis(300));
        cx.run_until_parked();
        if case["kind"] == "keyboard" {
            cx.update(|window, cx| {
                app.update(cx, |view, cx| {
                    view.run_shortcut(Action::ListPlayDefault, window, cx)
                })
            });
        } else {
            let center = cx.debug_bounds("title-credit-artwork-1").unwrap().center();
            cx.simulate_mouse_move(center, None, Modifiers::none());
            cx.run_until_parked();
            let center = cx.debug_bounds("title-credit-play-1").unwrap().center();
            cx.simulate_click(center, Modifiers::none());
        }
        cx.run_until_parked();
        app.read_with(cx, |view, _| {
            assert_eq!(
                serde_json::json!(
                    view.state
                        .queue
                        .ordered()
                        .iter()
                        .map(|entry| &entry.item.id)
                        .collect::<Vec<_>>()
                ),
                case["result"]["ids"],
                "{case}"
            );
            assert!(!view.playing);
        });
    }
    std::fs::remove_dir_all(dir).unwrap();
}

#[gpui::test]
fn favorite_shortcuts_and_remote_writes_refresh_artist_membership(cx: &mut TestAppContext) {
    use feishin_core::{
        api::Api,
        home::Kind,
        model::{Server, ServerType, Session},
        shortcuts::Action,
    };
    use gpui::VisualTestContext;
    use serde_json::json;
    use std::{
        io::{BufRead, BufReader, Write},
        net::TcpListener,
        sync::{
            Arc, Mutex,
            atomic::{AtomicBool, Ordering},
        },
        thread,
        time::{Duration, Instant},
    };
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    listener.set_nonblocking(true).unwrap();
    let server = Server {
        id: uuid::Uuid::new_v4(),
        name: "Mutation fixture".into(),
        url: format!("http://{}", listener.local_addr().unwrap()),
        username: "fixture".into(),
        kind: ServerType::Navidrome,
        legacy_auth: false,
        options: Default::default(),
    };
    let calls = Arc::new(Mutex::new(Vec::<String>::new()));
    let values = Arc::new(Mutex::new((false, 0_u8)));
    let fail = Arc::new(AtomicBool::new(false));
    let hold = Arc::new(AtomicBool::new(false));
    let done = Arc::new(AtomicBool::new(false));
    let (requests, confirmed, reject, gate, stop) = (
        calls.clone(),
        values.clone(),
        fail.clone(),
        hold.clone(),
        done.clone(),
    );
    let worker = thread::spawn(move || {
        while !stop.load(Ordering::Relaxed) {
            let Ok((mut socket, _)) = listener.accept() else {
                thread::sleep(Duration::from_millis(2));
                continue;
            };
            socket.set_nonblocking(false).unwrap();
            socket
                .set_read_timeout(Some(Duration::from_secs(2)))
                .unwrap();
            let mut reader = BufReader::new(socket.try_clone().unwrap());
            let mut first = String::new();
            reader.read_line(&mut first).unwrap();
            loop {
                let mut line = String::new();
                reader.read_line(&mut line).unwrap();
                if line == "\r\n" || line.is_empty() {
                    break;
                }
            }
            let url = gpui::http_client::Url::parse(&format!(
                "http://fixture{}",
                first.split_whitespace().nth(1).unwrap()
            ))
            .unwrap();
            let artist_query = url.path() == "/api/song"
                && url
                    .query_pairs()
                    .any(|(key, value)| key == "album_artist_id" && value == "artist");
            requests.lock().unwrap().push(if artist_query {
                "/api/song".into()
            } else {
                url.to_string()
            });
            let mutation = url.path().starts_with("/rest/");
            if mutation {
                let deadline = Instant::now() + Duration::from_secs(10);
                while gate.load(Ordering::Relaxed) && Instant::now() < deadline {
                    thread::sleep(Duration::from_millis(2));
                }
            }
            let mut status = "200 OK";
            let body = if mutation && reject.load(Ordering::Relaxed) {
                json!({"subsonic-response":{"status":"failed","error":{"code":0,"message":"mutation blocked"}}})
            } else if mutation {
                let params = url.query_pairs().collect::<std::collections::HashMap<_, _>>();
                let mut values = confirmed.lock().unwrap();
                match url.path() {
                    "/rest/star.view" => values.0 = true,
                    "/rest/unstar.view" => values.0 = false,
                    "/rest/setRating.view" => values.1 = params["rating"].parse().unwrap(),
                    _ => { status = "404 Not Found"; }
                }
                json!({"subsonic-response":{"status":"ok","version":"1.16.1"}})
            } else {
                let (favorite, rating) = *confirmed.lock().unwrap();
                let song = json!({"id":"song","title":"Song","albumArtistId":"artist","albumArtist":"Artist","starred":favorite,"rating":rating});
                match url.path() {
                    "/api/song" => {
                        if artist_query {json!([song])} else {
                            assert!(url.query_pairs().any(|(key, value)| key == "album_id" && value == "album"));
                            json!([])
                        }
                    }
                    "/api/song/song" => song,
                    "/api/artist/artist" => json!({"id":"artist","name":"Artist"}),
                    _ => { status = "404 Not Found"; json!({}) }
                }
            }.to_string();
            let _ = write!(
                socket,
                "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
        }
    });
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!("feishin-library-writes-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.sidebar.playlist_list = false;
        state.settings.artist_items.clear();
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.run_until_parked();
    let song = Item {
        id: "song".into(),
        name: "Song".into(),
        kind: ItemKind::Song,
        server_id: server.id,
        ..Default::default()
    };
    let foreign = Item {
        server_id: uuid::Uuid::new_v4(),
        ..song.clone()
    };
    let artist = Item {
        id: "artist".into(),
        name: "Artist".into(),
        kind: ItemKind::AlbumArtist,
        ..song.clone()
    };
    cx.update(|_, cx| {
        app.update(cx, |view, _| {
            view.sessions.insert(
                server.id,
                Api::new(server.clone(), Session::default()).unwrap(),
            );
            view.route = Route::Detail(Box::new(artist.clone()));
            view.artist_overview = true;
            view.artist_info_target = Some((server.id, "artist".into()));
            view.artist_info = Some(ArtistInfo::default());
            view.artist_sections
                .insert("favoriteSongs".into(), Default::default());
            view.artist_sections.insert(
                "topSongs".into(),
                crate::artist_overview::Section {
                    items: vec![song.clone()],
                    generation: 123,
                    page: 2,
                    ..Default::default()
                },
            );
            view.items = vec![song.clone(), foreign.clone()];
            view.info_items = vec![song.clone()];
            view.previous_played = Some(song.clone());
            view.player_related.items = vec![song.clone()];
            view.home_sections.insert(
                Kind::RecentlyPlayed,
                crate::home::Section {
                    items: vec![song.clone()],
                    ..Default::default()
                },
            );
            view.album_metadata_cache
                .insert("cached".into(), Some(song.clone()));
            view.album_tracks.insert(
                "album".into(),
                crate::details::AlbumTracks {
                    items: vec![song.clone()],
                    ..Default::default()
                },
            );
            view.state
                .queue
                .add(vec![song.clone(), song.clone()], Enqueue::Now);
            view.last_played = Some((view.state.queue.entries[0].key, song.clone()));
            view.state.queue.position = 19.;
        })
    });
    let history = app.read_with(cx, |view, _| view.history.clone());
    let queue = app.read_with(cx, |view, _| {
        (view.state.queue.order.clone(), view.state.queue.current)
    });
    let wait = |cx: &mut VisualTestContext, check: &dyn Fn(&Feishin) -> bool| {
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            cx.run_until_parked();
            if app.read_with(cx, |view, _| check(view)) {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "Mutation did not finish: {:?}",
                app.read_with(cx, |view, _| (view.message.clone(), view.loading))
            );
            thread::sleep(Duration::from_millis(2));
        }
    };
    let overview_ready = |view: &Feishin| {
        view.favorite_requests == 0
            && view.rating_requests == 0
            && !view.artist_sections["favoriteSongs"].loading
    };
    for (action, expected) in [
        (Action::FavoriteCurrentAdd, true),
        (Action::FavoritePreviousRemove, false),
        (Action::FavoritePreviousToggle, true),
        (Action::FavoriteCurrentToggle, false),
        (Action::FavoritePreviousAdd, true),
        (Action::FavoriteCurrentRemove, false),
    ] {
        cx.update(|window, cx| app.update(cx, |view, cx| view.run_shortcut(action, window, cx)));
        wait(cx, &overview_ready);
        app.read_with(cx, |view, _| {
            assert_eq!(
                view.artist_sections["favoriteSongs"].items.len(),
                usize::from(expected)
            );
            if !expected {
                assert!(view.artist_sections["favoriteSongs"].selected.is_empty());
                assert!(
                    view.artist_sections["favoriteSongs"]
                        .selection_order
                        .is_empty()
                );
            }
            assert_eq!(view.artist_sections["topSongs"].generation, 123);
            assert_eq!(view.artist_sections["topSongs"].page, 2);
            for item in view.items[..1]
                .iter()
                .chain(&view.info_items)
                .chain(&view.player_related.items)
                .chain(view.previous_played.iter())
                .chain(view.last_played.iter().map(|(_, item)| item))
                .chain(view.state.queue.entries.iter().map(|entry| &entry.item))
                .chain(&view.artist_sections["topSongs"].items)
                .chain(&view.home_sections[&Kind::RecentlyPlayed].items)
                .chain(view.album_metadata_cache.values().flatten())
                .chain(&view.album_tracks["album"].items)
            {
                assert_eq!(item.favorite, expected, "Stale item after {action:?}");
            }
            assert!(!view.items[1].favorite);
        });
    }
    let reads = || {
        calls
            .lock()
            .unwrap()
            .iter()
            .filter(|path| path.as_str() == "/api/song")
            .count()
    };
    assert_eq!(reads(), 6);
    // A failed write cannot add an item or trigger a membership refresh.
    fail.store(true, Ordering::Relaxed);
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            view.run_shortcut(Action::FavoriteCurrentAdd, window, cx)
        })
    });
    wait(cx, &overview_ready);
    assert_eq!(reads(), 6);
    assert!(
        app.read_with(cx, |view, _| view.message.contains("mutation blocked")
            && !view.previous_played.as_ref().unwrap().favorite)
    );
    fail.store(false, Ordering::Relaxed);
    // A delayed previous-track reply must not replace a newer previous track.
    hold.store(true, Ordering::Relaxed);
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            view.run_shortcut(Action::FavoritePreviousAdd, window, cx)
        })
    });
    cx.update(|_, cx| {
        app.update(cx, |view, _| {
            view.previous_played = Some(Item {
                id: "new-previous".into(),
                ..song.clone()
            })
        })
    });
    hold.store(false, Ordering::Relaxed);
    wait(cx, &overview_ready);
    assert!(app.read_with(cx, |view, _| {
        view.previous_played
            .as_ref()
            .is_some_and(|item| item.id == "new-previous" && !item.favorite)
    }));
    // Confirmed remote changes use the same cache and artist invalidation path.
    for (event, value, expected_count, failed) in [
        ("favorite", json!(false), 0, false),
        ("rating", json!(4), 1, false),
        ("rating", json!(0), 0, false),
        ("favorite", json!(true), 0, true),
        ("rating", json!(5), 0, true),
    ] {
        fail.store(failed, Ordering::Relaxed);
        let before = reads();
        let (reply, mut response) = tokio::sync::oneshot::channel();
        cx.update(|window, cx| {
            app.update(cx, |view, cx| {
                view.state.settings.artist_favorites_rating = event == "rating";
                let mut message =
                    json!({"event":event,"id":"song","serverId":server.id,"requestId":"write"});
                message[event] = value;
                view.remote_request(feishin_core::remote::Request { message, reply }, window, cx);
                assert_eq!(view.favorite_requests, usize::from(event == "favorite"));
                assert_eq!(view.rating_requests, usize::from(event == "rating"));
            })
        });
        let deadline = Instant::now() + Duration::from_secs(5);
        let replies = loop {
            cx.run_until_parked();
            if let Ok(replies) = response.try_recv() {
                break replies;
            }
            assert!(Instant::now() < deadline);
            thread::sleep(Duration::from_millis(2));
        };
        assert_eq!(replies.iter().any(|reply| reply["event"] == event), !failed);
        assert_eq!(
            replies.iter().any(|reply| reply["data"]["error"]
                .as_str()
                .is_some_and(|error| error.contains("mutation blocked"))),
            failed,
            "{replies:?}"
        );
        wait(cx, &overview_ready);
        assert_eq!(reads(), before + usize::from(!failed));
        app.read_with(cx, |view, _| {
            assert_eq!(
                view.artist_sections["favoriteSongs"].items.len(),
                expected_count
            );
            assert_eq!(
                view.info_items[0].rating,
                if event == "rating" && expected_count == 1 {
                    4
                } else {
                    0
                }
            );
            assert!(!view.info_items[0].favorite);
        });
    }
    fail.store(false, Ordering::Relaxed);
    // Artist songs expose all five choices and selecting the committed value clears it.
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.state.settings.artist_items = vec![feishin_core::releases::Setting {
                id: "topSongs".into(),
                disabled: false,
            }];
            let mut config = feishin_core::lists::default_for("song");
            for column in &mut config.table.columns {
                column.is_enabled =
                    matches!(column.id.as_str(), "name" | "userFavorite" | "userRating");
                column.width = if column.id == "name" { 280. } else { 100. };
            }
            view.state.settings.lists.insert("song".into(), config);
            cx.notify();
        })
    });
    cx.run_until_parked();
    for (selected, expected) in [(2, 2), (2, 0), (4, 4), (4, 0)] {
        let row = cx.debug_bounds("artist-section-song-topSongs-0").unwrap();
        cx.simulate_mouse_move(row.center(), None, gpui::Modifiers::none());
        cx.run_until_parked();
        let center = cx
            .debug_bounds(&format!("overview-song-rating-topSongs-0-{selected}"))
            .unwrap()
            .center();
        cx.simulate_click(center, gpui::Modifiers::none());
        cx.run_until_parked();
        cx.executor().advance_clock(Duration::from_millis(100));
        wait(cx, &|view| {
            overview_ready(view) && view.info_items[0].rating == expected
        });
        assert_eq!(
            app.read_with(cx, |view, _| view.artist_sections["favoriteSongs"]
                .items
                .len()),
            usize::from(expected > 2)
        );
    }
    // Expanded album controls write the album, leaving same-server songs unchanged.
    let before = reads();
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.route = Route::Library(ItemKind::Album);
            view.items = vec![Item {
                id: "album".into(),
                name: "Album".into(),
                kind: ItemKind::Album,
                ..song.clone()
            }];
            view.state.settings.album_group.show_favorite_rating = true;
            let mut config = view.list_config();
            config.display = "detail".into();
            view.state.settings.lists.insert(view.list_key(), config);
            cx.notify();
        })
    });
    cx.run_until_parked();
    for expected in [5, 0] {
        let center = cx.debug_bounds("album-group-rating-0-5").unwrap().center();
        cx.simulate_click(center, gpui::Modifiers::none());
        cx.run_until_parked();
        cx.executor().advance_clock(Duration::from_millis(100));
        wait(cx, &|view| {
            view.rating_requests == 0 && view.items[0].rating == expected
        });
        assert!(app.read_with(cx, |view, _| {
            view.state
                .queue
                .entries
                .iter()
                .all(|entry| entry.item.rating == 0)
        }));
        assert_eq!(reads(), before);
    }
    cx.update(|_, cx| {
        app.update(cx, |view, _| {
            view.route = Route::Detail(Box::new(artist.clone()));
            view.items = vec![song.clone(), foreign.clone()];
        })
    });
    // A mutation on another account must not reload this artist's sections.
    let before = reads();
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.apply_library_values(
                &[Item {
                    favorite: true,
                    ..foreign.clone()
                }],
                true,
                false,
                cx,
            )
        })
    });
    cx.run_until_parked();
    assert_eq!(reads(), before);
    assert!(app.read_with(cx, |view, _| view.items[1].favorite));
    // Dedicated favorite and rated tabs refresh membership without new history.
    for tab in [ArtistTab::Favorites, ArtistTab::Rated] {
        cx.update(|_, cx| {
            app.update(cx, |view, cx| {
                view.artist_overview = false;
                view.artist_tab = tab;
                view.set_library_values(
                    vec![song.clone()],
                    (tab == ArtistTab::Favorites).then_some(true),
                    (tab == ArtistTab::Rated).then_some(3),
                    cx,
                );
            })
        });
        wait(cx, &|view| {
            view.favorite_requests == 0 && view.rating_requests == 0 && !view.loading
        });
        assert!(app.read_with(cx, |view, _| view.items.len() == 1
            && view.items[0].id == "song"));
        cx.update(|_, cx| {
            app.update(cx, |view, cx| {
                view.set_library_values(
                    vec![song.clone()],
                    (tab == ArtistTab::Favorites).then_some(false),
                    (tab == ArtistTab::Rated).then_some(0),
                    cx,
                );
            })
        });
        wait(cx, &|view| {
            view.favorite_requests == 0 && view.rating_requests == 0 && !view.loading
        });
        assert!(app.read_with(cx, |view, _| view.items.is_empty()));
    }
    app.read_with(cx, |view, _| {
        assert_eq!(view.history, history);
        assert_eq!(
            (view.state.queue.order.clone(), view.state.queue.current),
            queue
        );
        assert_eq!(view.state.queue.position, 19.);
        assert!(!view.loaded && !view.playing);
    });
    // The overview and both full lists share sort preferences; ID retains server rank.
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.artist_overview = true;
            view.state.settings.artist_items = vec![feishin_core::releases::Setting {
                id: "favoriteSongs".into(),
                disabled: false,
            }];
            view.artist_sections.insert(
                "favoriteSongs".into(),
                crate::artist_overview::Section {
                    items: ["Zebra", "Alpha", "Middle", "Middle"]
                        .into_iter()
                        .enumerate()
                        .map(|(index, name)| Item {
                            id: index.to_string(),
                            name: name.into(),
                            ..song.clone()
                        })
                        .collect(),
                    ..Default::default()
                },
            );
            view.set_artist_favorite_sort(feishin_core::model::Sort::Id, false, cx);
            assert_eq!(
                view.artist_section_indices("favoriteSongs", cx),
                [0, 1, 2, 3]
            );
            view.set_artist_favorite_sort(feishin_core::model::Sort::Name, false, cx);
            assert_eq!(
                view.artist_section_indices("favoriteSongs", cx),
                [1, 2, 3, 0]
            );
        })
    });
    cx.run_until_parked();
    let center = cx
        .debug_bounds("artist-favorite-sort-direction")
        .unwrap()
        .center();
    cx.simulate_click(center, gpui::Modifiers::none());
    cx.run_until_parked();
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            assert_eq!(
                view.artist_section_indices("favoriteSongs", cx),
                [0, 2, 3, 1]
            );
            for tab in [ArtistTab::Favorites, ArtistTab::Rated] {
                view.artist_overview = false;
                view.artist_tab = tab;
                view.restore_view();
                assert_eq!(view.sort, feishin_core::model::Sort::Name);
                assert!(view.descending);
            }
        })
    });
    done.store(true, Ordering::Relaxed);
    worker.join().unwrap();
    std::fs::remove_dir_all(dir).unwrap();
}

#[gpui::test]
fn rating_pointer_keyboard_and_failures_update_all_surfaces_without_navigation(
    cx: &mut TestAppContext,
) {
    use feishin_core::{
        api::Api,
        lists::Column,
        model::{Server, ServerType, Session},
        shortcuts::Action,
    };
    use gpui::{Modifiers, VisualTestContext};
    use std::{
        io::{BufRead, BufReader, Write},
        net::TcpListener,
        sync::{
            Arc, Mutex,
            atomic::{AtomicBool, Ordering},
        },
        thread,
        time::{Duration, Instant},
    };
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    listener.set_nonblocking(true).unwrap();
    let server = Server {
        id: uuid::Uuid::new_v4(),
        name: "Rating fixture".into(),
        url: format!("http://{}", listener.local_addr().unwrap()),
        username: "fixture".into(),
        kind: ServerType::Subsonic,
        legacy_auth: false,
        options: Default::default(),
    };
    let requests = Arc::new(Mutex::new(Vec::new()));
    let favorite_requests = Arc::new(Mutex::new(Vec::new()));
    let favorite_calls = favorite_requests.clone();
    let fail = Arc::new(AtomicBool::new(false));
    let hold = Arc::new(AtomicBool::new(false));
    let gate = hold.clone();
    let done = Arc::new(AtomicBool::new(false));
    let (calls, reject, stop) = (requests.clone(), fail.clone(), done.clone());
    let fixture = thread::spawn(move || {
        while !stop.load(Ordering::Relaxed) {
            let Ok((mut socket, _)) = listener.accept() else {
                thread::sleep(Duration::from_millis(2));
                continue;
            };
            socket.set_nonblocking(false).unwrap();
            socket
                .set_read_timeout(Some(Duration::from_secs(2)))
                .unwrap();
            let mut reader = BufReader::new(socket.try_clone().unwrap());
            let mut first = String::new();
            reader.read_line(&mut first).unwrap();
            loop {
                let mut line = String::new();
                reader.read_line(&mut line).unwrap();
                if line == "\r\n" || line.is_empty() {
                    break;
                }
            }
            let url = gpui::http_client::Url::parse(&format!(
                "http://fixture{}",
                first.split_whitespace().nth(1).unwrap()
            ))
            .unwrap();
            let mut status = "200 OK";
            let body = if url.path().contains("setRating") {
                let params = url
                    .query_pairs()
                    .collect::<std::collections::HashMap<_, _>>();
                assert_eq!(params.get("id").unwrap(), "song");
                calls
                    .lock()
                    .unwrap()
                    .push(params["rating"].parse::<u8>().unwrap());
                let deadline = Instant::now() + Duration::from_secs(10);
                while gate.load(Ordering::Relaxed) && Instant::now() < deadline {
                    thread::sleep(Duration::from_millis(2));
                }
                if reject.load(Ordering::Relaxed) {
                    r#"{"subsonic-response":{"status":"failed","error":{"code":0,"message":"rating blocked"}}}"#
                } else {
                    r#"{"subsonic-response":{"status":"ok","version":"1.16.1"}}"#
                }
            } else if url.path().ends_with("/star.view") || url.path().ends_with("/unstar.view") {
                favorite_calls
                    .lock()
                    .unwrap()
                    .push(url.path().ends_with("/star.view"));
                let deadline = Instant::now() + Duration::from_secs(10);
                while gate.load(Ordering::Relaxed) && Instant::now() < deadline {
                    thread::sleep(Duration::from_millis(2));
                }
                if reject.load(Ordering::Relaxed) {
                    r#"{"subsonic-response":{"status":"failed","error":{"code":0,"message":"favorite blocked"}}}"#
                } else {
                    r#"{"subsonic-response":{"status":"ok","version":"1.16.1"}}"#
                }
            } else {
                status = "404 Not Found";
                "{}"
            };
            let _ = write!(
                socket,
                "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
        }
    });
    cx.set_assets(crate::icons::Assets);
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!("feishin-rating-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        window.activate_accessibility_for_test();
        let mut state = fixture_state();
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.simulate_resize(gpui::size(gpui::px(1400.), gpui::px(1000.)));
    cx.run_until_parked();
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.state.active_server = Some(server.id);
            view.state.servers.push(server.clone());
            view.sessions.insert(
                server.id,
                Api::new(server.clone(), Session::default()).unwrap(),
            );
            view.route = Route::Library(ItemKind::Song);
            let song = Item {
                id: "song".into(),
                name: "Rated song".into(),
                kind: ItemKind::Song,
                server_id: server.id,
                ..Default::default()
            };
            view.items = vec![song.clone()];
            view.player_related.items = vec![song.clone()];
            view.info_items = vec![song.clone()];
            view.state.queue.add(vec![song.clone(), song], Enqueue::Now);
            view.selected.insert(0);
            let mut config = view.list_config();
            config.display = "table".into();
            config.table.columns = vec![
                Column {
                    id: "name".into(),
                    is_enabled: true,
                    width: 250.,
                    ..Default::default()
                },
                Column {
                    id: "userRating".into(),
                    is_enabled: true,
                    width: 150.,
                    ..Default::default()
                },
            ];
            config.table.columns.push(Column {
                id: "userFavorite".into(),
                is_enabled: true,
                width: 80.,
                ..Default::default()
            });
            view.state.settings.lists.insert(view.list_key(), config);
            cx.notify();
        })
    });
    cx.run_until_parked();
    let unchanged = app.read_with(cx, |view, _| {
        (
            view.route.clone(),
            view.history.clone(),
            view.state.queue.order.clone(),
            view.state.queue.current,
        )
    });
    fn click(cx: &mut VisualTestContext, id: &str) {
        if id.starts_with("column-") {
            let row = cx.debug_bounds("library-row-0").unwrap();
            cx.simulate_mouse_move(row.center(), None, Modifiers::none());
            cx.run_until_parked();
        }
        let center = cx
            .debug_bounds(id)
            .unwrap_or_else(|| panic!("Missing {id}"))
            .center();
        cx.simulate_mouse_move(center, None, Modifiers::none());
        cx.run_until_parked();
        cx.simulate_click(center, Modifiers::none());
        cx.run_until_parked();
    }
    let wait = |cx: &mut VisualTestContext, count: usize, expected: u8, failure: bool| {
        cx.run_until_parked();
        cx.executor().advance_clock(Duration::from_millis(100));
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            cx.run_until_parked();
            let ready = requests.lock().unwrap().len() == count
                && app.read_with(cx, |view, _| {
                    if failure {
                        view.message.contains("rating blocked")
                    } else {
                        view.items[0].rating == expected
                    }
                });
            if ready {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "Rating response not applied: count={count}, requests={:?}, state={:?}",
                requests.lock().unwrap(),
                app.read_with(cx, |view, _| (view.items[0].rating, view.message.clone()))
            );
            thread::sleep(Duration::from_millis(5));
        }
        let selected = cx.update(|window, _| {
            window
                .accessibility_tree_for_test()
                .unwrap()
                .nodes
                .iter()
                .filter(|(_, node)| {
                    node.role() == gpui::Role::RadioButton
                        && node.toggled() == Some(gpui::accesskit::Toggled::True)
                })
                .map(|(_, node)| node.label().unwrap().to_owned())
                .collect::<Vec<_>>()
        });
        if expected == 0 {
            assert!(selected.is_empty());
        } else {
            assert!(!selected.is_empty());
            assert!(
                selected
                    .iter()
                    .all(|label| label.ends_with(&format!("{expected}/5")))
            );
        }
        app.read_with(cx, |view, _| {
            for item in view
                .items
                .iter()
                .chain(&view.player_related.items)
                .chain(&view.info_items)
                .chain(view.state.queue.entries.iter().map(|entry| &entry.item))
            {
                assert_eq!(item.rating, expected);
                assert_eq!(
                    item.column_data.get("userRating").map(String::as_str),
                    Some(expected.to_string().as_str())
                );
            }
            assert_eq!(
                (
                    view.route.clone(),
                    view.history.clone(),
                    view.state.queue.order.clone(),
                    view.state.queue.current
                ),
                unchanged
            );
            assert_eq!(view.selected, std::collections::HashSet::from([0]));
            assert!(!view.playing);
            assert_eq!((view.favorite_requests, view.rating_requests), (0, 0));
        });
    };
    let mut count = 0;
    for (value, expected) in [(5, 5), (5, 0), (3, 3), (1, 1), (4, 4), (2, 2), (2, 0)] {
        click(cx, &format!("column-rating-0-{value}"));
        count += 1;
        wait(cx, count, expected, false);
    }
    // A burst within the original 100ms debounce sends only its final choice.
    click(cx, "player-rating-1");
    click(cx, "player-rating-3");
    click(cx, "player-rating-5");
    // A concurrent favorite change must survive the older rating request's snapshot.
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            let mut song = view.items[0].clone();
            song.favorite = true;
            view.update_library_item(&song);
            cx.notify();
        })
    });
    count += 1;
    wait(cx, count, 5, false);
    assert!(app.read_with(cx, |view, _| view.items[0].favorite));
    cx.simulate_keystrokes("left enter");
    count += 1;
    wait(cx, count, 4, false);
    cx.simulate_keystrokes("space");
    count += 1;
    wait(cx, count, 0, false);
    // Existing global/local rate commands share the same confirmed-update path.
    cx.update(|window, cx| app.update(cx, |view, cx| view.run_shortcut(Action::Rate1, window, cx)));
    count += 1;
    wait(cx, count, 1, false);
    fail.store(true, Ordering::Relaxed);
    click(cx, "column-rating-0-5");
    count += 1;
    wait(cx, count, 1, true);
    assert_eq!(
        *requests.lock().unwrap(),
        [5, 0, 3, 1, 4, 2, 0, 5, 4, 0, 1, 5]
    );
    fail.store(false, Ordering::Relaxed);
    let reference: serde_json::Value =
        serde_json::from_str(include_str!("../assets/rating-reference.json")).unwrap();
    for (index, case) in reference.as_array().unwrap().iter().enumerate() {
        cx.update(|_, cx| {
            app.update(cx, |view, cx| {
                view.state.settings.language = ["en", "fr", "ar", "ja"][index % 4].into();
                let mut backend = server.clone();
                backend.kind = if index % 2 == 0 {
                    ServerType::Subsonic
                } else {
                    ServerType::Navidrome
                };
                view.sessions
                    .insert(server.id, Api::new(backend, Session::default()).unwrap());
                let mut song = view.items[0].clone();
                song.set_rating(case["current"].as_u64().unwrap() as u8);
                view.update_library_item(&song);
                cx.notify();
            })
        });
        cx.run_until_parked();
        click(cx, &format!("column-rating-0-{}", case["selected"]));
        count += 1;
        wait(cx, count, case["result"].as_u64().unwrap() as u8, false);
    }
    hold.store(true, Ordering::Relaxed);
    click(cx, "column-rating-0-4");
    cx.executor().advance_clock(Duration::from_millis(100));
    let deadline = Instant::now() + Duration::from_secs(5);
    while requests.lock().unwrap().len() != count + 1 {
        cx.run_until_parked();
        assert!(Instant::now() < deadline, "Rating request did not start");
        thread::sleep(Duration::from_millis(2));
    }
    cx.run_until_parked();
    assert_eq!(app.read_with(cx, |view, _| view.rating_requests), 1);
    assert!(
        !cx.update(|_, cx| cx.has_active_drag()),
        "Rating click must not start a row drag"
    );
    let radio_states = cx.update(|window, _| {
        window
            .accessibility_tree_for_test()
            .unwrap()
            .nodes
            .iter()
            .filter(|(_, node)| node.role() == gpui::Role::RadioButton)
            .map(|(_, node)| (node.label().unwrap().to_owned(), node.is_disabled()))
            .collect::<Vec<_>>()
    });
    assert!(
        radio_states.iter().any(|(_, disabled)| *disabled),
        "{radio_states:?}"
    );
    click(cx, "column-rating-0-1");
    cx.executor().advance_clock(Duration::from_millis(200));
    cx.run_until_parked();
    assert_eq!(requests.lock().unwrap().len(), count + 1);
    hold.store(false, Ordering::Relaxed);
    count += 1;
    wait(cx, count, 4, false);
    // Return to an unrated row for hover visibility and keyboard accessibility.
    click(cx, "column-rating-0-4");
    count += 1;
    wait(cx, count, 0, false);
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            let mut song = view.items[0].clone();
            song.favorite = false;
            view.update_library_item(&song);
            cx.notify();
        })
    });
    cx.run_until_parked();
    hold.store(true, Ordering::Relaxed);
    click(cx, "column-favorite-0");
    let deadline = Instant::now() + Duration::from_secs(5);
    while favorite_requests.lock().unwrap().len() != 1 {
        cx.run_until_parked();
        assert!(Instant::now() < deadline);
        thread::sleep(Duration::from_millis(2));
    }
    cx.run_until_parked();
    assert_eq!(app.read_with(cx, |view, _| view.favorite_requests), 1);
    click(cx, "column-favorite-0");
    assert_eq!(*favorite_requests.lock().unwrap(), [true]);
    hold.store(false, Ordering::Relaxed);
    for (expected, failure) in [(true, false), (false, false), (false, true)] {
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            cx.run_until_parked();
            let ready = app.read_with(cx, |view, _| {
                view.favorite_requests == 0
                    && view.items[0].favorite == expected
                    && (!failure || view.message.contains("favorite blocked"))
            });
            if ready {
                break;
            }
            assert!(Instant::now() < deadline, "Favorite response not applied");
            thread::sleep(Duration::from_millis(2));
        }
        app.read_with(cx, |view, _| {
            assert!(
                view.state
                    .queue
                    .entries
                    .iter()
                    .all(|entry| entry.item.favorite == expected && entry.item.rating == 0)
            );
            assert_eq!(view.rating_requests, 0);
        });
        if failure {
            break;
        }
        if !expected {
            fail.store(true, Ordering::Relaxed);
        }
        click(cx, "column-favorite-0");
    }
    assert_eq!(*favorite_requests.lock().unwrap(), [true, false, true]);
    fail.store(false, Ordering::Relaxed);
    cx.simulate_resize(gpui::size(gpui::px(960.), gpui::px(640.)));
    cx.run_until_parked();
    let bounds = cx.debug_bounds("player-rating").unwrap();
    assert!(bounds.origin.x >= gpui::px(0.) && bounds.right() <= gpui::px(960.));
    cx.simulate_mouse_move(
        gpui::point(gpui::px(10.), gpui::px(10.)),
        None,
        Modifiers::none(),
    );
    cx.run_until_parked();
    assert_eq!(
        cx.update(|window, _| window
            .accessibility_tree_for_test()
            .unwrap()
            .nodes
            .iter()
            .filter(|(_, node)| node.role() == gpui::Role::RadioButton)
            .count()),
        5,
        "Unrated table controls stay hidden until the row is hovered"
    );
    assert!(cx.update(|window, _| {
        window
            .accessibility_tree_for_test()
            .unwrap()
            .nodes
            .iter()
            .all(|(_, node)| node.label() != Some("♡"))
    }));
    let row = cx.debug_bounds("library-row-0").unwrap();
    cx.simulate_mouse_move(row.center(), None, Modifiers::none());
    cx.run_until_parked();
    // Screen readers see separate, labeled radio choices and the committed selection.
    let radios = cx.update(|window, _| {
        window
            .accessibility_tree_for_test()
            .unwrap()
            .nodes
            .iter()
            .filter(|(_, node)| node.role() == gpui::Role::RadioButton)
            .map(|(_, node)| node.clone())
            .collect::<Vec<_>>()
    });
    assert!(radios.len() >= 10);
    assert!(
        radios
            .iter()
            .all(|node| node.label().is_some_and(|label| label.contains("/5")))
    );
    cx.simulate_resize(gpui::size(gpui::px(1600.), gpui::px(1000.)));
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            let mut config = view.list_config();
            config.table.columns.push(Column {
                id: "actions".into(),
                is_enabled: true,
                width: 600.,
                ..Default::default()
            });
            view.state.settings.lists.insert(view.list_key(), config);
            cx.notify();
        })
    });
    cx.run_until_parked();
    assert!(cx.debug_bounds("rating-0").is_some());
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            let mut active = server.clone();
            active.id = uuid::Uuid::new_v4();
            active.kind = ServerType::Navidrome;
            view.state.active_server = Some(active.id);
            view.sessions
                .insert(active.id, Api::new(active, Session::default()).unwrap());
            let mut foreign = server.clone();
            foreign.kind = ServerType::Jellyfin;
            view.sessions
                .insert(server.id, Api::new(foreign, Session::default()).unwrap());
            cx.notify();
        })
    });
    cx.run_until_parked();
    cx.refresh().unwrap();
    cx.run_until_parked();
    assert!(
        cx.update(|window, _| window
            .accessibility_tree_for_test()
            .unwrap()
            .nodes
            .iter()
            .all(|(_, node)| node.role() != gpui::Role::RadioButton)),
        "Rating support follows the item's server"
    );
    // Header actions share the mutation path but target the album, not the playing song.
    let preserved = app.read_with(cx, |view, _| {
        (
            view.history.clone(),
            serde_json::to_value(&view.state.queue).unwrap(),
        )
    });
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.sessions.insert(
                server.id,
                Api::new(server.clone(), Session::default()).unwrap(),
            );
            view.route = Route::Detail(Box::new(Item {
                id: "song".into(),
                name: "Header album".into(),
                kind: ItemKind::Album,
                server_id: server.id,
                ..Default::default()
            }));
            view.items.clear();
            view.album_details_scroll
                .scroll_to(gpui::ListOffset::default());
            cx.notify();
        })
    });
    cx.run_until_parked();
    assert_eq!(
        cx.debug_bounds("detail-rating-4").unwrap().size.width,
        gpui::px(16.)
    );
    assert_eq!(
        cx.debug_bounds("detail-rating").unwrap().size.width,
        gpui::px(104.)
    );
    let before = requests.lock().unwrap().len();
    click(cx, "detail-rating-4");
    cx.executor().advance_clock(Duration::from_millis(100));
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        cx.run_until_parked();
        if app.read_with(cx, |view, _| {
            matches!(&view.route, Route::Detail(item) if item.rating == 4)
                && view.rating_requests == 0
        }) {
            break;
        }
        assert!(
            Instant::now() < deadline,
            "Header rating response not applied"
        );
        thread::sleep(Duration::from_millis(2));
    }
    assert_eq!(requests.lock().unwrap().len(), before + 1);
    assert_eq!(requests.lock().unwrap().last(), Some(&4));
    click(cx, "detail-favorite");
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        cx.run_until_parked();
        if app.read_with(cx, |view, _| {
            matches!(&view.route, Route::Detail(item) if item.favorite)
                && view.favorite_requests == 0
        }) {
            break;
        }
        assert!(
            Instant::now() < deadline,
            "Header favorite response not applied"
        );
        thread::sleep(Duration::from_millis(2));
    }
    let before = (
        requests.lock().unwrap().len(),
        favorite_requests.lock().unwrap().len(),
    );
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.rating_requests = 1;
            view.favorite_requests = 1;
            cx.notify();
        })
    });
    cx.run_until_parked();
    click(cx, "detail-rating-2");
    click(cx, "detail-favorite");
    cx.executor().advance_clock(Duration::from_millis(100));
    cx.run_until_parked();
    assert_eq!(
        (
            requests.lock().unwrap().len(),
            favorite_requests.lock().unwrap().len()
        ),
        before
    );
    app.read_with(cx, |view, _| {
        assert_eq!(view.history, preserved.0);
        assert_eq!(
            serde_json::to_value(&view.state.queue).unwrap(),
            preserved.1
        );
    });
    for (kind, server_kind, enabled, count) in [
        (ItemKind::Album, ServerType::Subsonic, true, 10),
        (ItemKind::Artist, ServerType::Subsonic, true, 5),
        (ItemKind::AlbumArtist, ServerType::Subsonic, true, 5),
        (ItemKind::AlbumArtist, ServerType::Navidrome, true, 10),
        (ItemKind::Artist, ServerType::Navidrome, true, 10),
        (ItemKind::Album, ServerType::Jellyfin, true, 0),
        (ItemKind::AlbumArtist, ServerType::Navidrome, false, 0),
    ] {
        cx.update(|_, cx| {
            app.update(cx, |view, cx| {
                view.rating_requests = 0;
                view.favorite_requests = 0;
                view.state.settings.show_ratings = enabled;
                view.state.settings.show_favorites = enabled;
                if let Route::Detail(item) = &mut view.route {
                    item.kind = kind;
                }
                let mut source = server.clone();
                source.kind = server_kind;
                view.sessions
                    .insert(server.id, Api::new(source, Session::default()).unwrap());
                cx.notify();
            })
        });
        cx.run_until_parked();
        cx.refresh().unwrap();
        cx.run_until_parked();
        assert_eq!(
            cx.update(|window, _| window
                .accessibility_tree_for_test()
                .unwrap()
                .nodes
                .iter()
                .filter(|(_, node)| node.role() == gpui::Role::RadioButton)
                .count()),
            count,
            "Header rating visibility: {kind:?}/{server_kind:?}/{enabled}"
        );
        if !enabled {
            assert!(cx.update(|window, _| {
                window
                    .accessibility_tree_for_test()
                    .unwrap()
                    .nodes
                    .iter()
                    .all(|(_, node)| node.label() != Some("Unfavorite"))
            }));
        }
    }
    done.store(true, Ordering::Relaxed);
    fixture.join().unwrap();
    let _ = std::fs::remove_dir_all(dir);
}

#[gpui::test]
fn player_configuration_popover_preserves_browsing_and_matches_live_controls(
    cx: &mut TestAppContext,
) {
    use feishin_core::transition::{Curve, Mode};
    use gpui::{
        Modifiers, MouseButton, Role, VisualTestContext,
        accesskit::{Action, ActionData, ActionRequest, TreeId},
        point, px,
    };
    fn click(cx: &mut VisualTestContext, selector: &str) {
        let bounds = cx.debug_bounds(selector).unwrap();
        cx.simulate_click(bounds.center(), Modifiers::none());
        cx.run_until_parked();
    }
    fn node(
        cx: &mut VisualTestContext,
        role: Role,
        label: &str,
    ) -> (gpui::accesskit::NodeId, gpui::accesskit::Node) {
        cx.update(|window, _| {
            let tree = window.accessibility_tree_for_test().unwrap();
            let consumer = accesskit_consumer::Tree::new(tree.clone(), true);
            tree.nodes
                .iter()
                .find(|(id, node)| {
                    node.role() == role
                        && consumer
                            .state()
                            .node_by_tree_local_id(*id, TreeId::ROOT)
                            .unwrap()
                            .label()
                            .as_deref()
                            == Some(label)
                })
                .unwrap_or_else(|| panic!("Missing {role:?}: {label}"))
                .clone()
        })
    }
    fn click_node(cx: &mut VisualTestContext, role: Role, label: &str) {
        let (_, node) = node(cx, role, label);
        let bounds = node.bounds().unwrap();
        let position = cx.update(|window, _| {
            let scale = f64::from(window.scale_factor());
            point(
                px(((bounds.x0 + bounds.x1) / (2. * scale)) as f32),
                px(((bounds.y0 + bounds.y1) / (2. * scale)) as f32),
            )
        });
        cx.simulate_click(position, Modifiers::none());
        cx.run_until_parked();
    }
    fn slider(cx: &mut VisualTestContext, label: &str, value: f64) {
        let (id, _) = node(cx, Role::Slider, label);
        cx.update(|window, cx| {
            window.dispatch_accessibility_action_for_test(
                ActionRequest {
                    action: Action::SetValue,
                    target_tree: TreeId::ROOT,
                    target_node: id,
                    data: Some(ActionData::NumericValue(value)),
                },
                cx,
            )
        });
        cx.run_until_parked();
    }
    cx.set_assets(crate::icons::Assets);
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!("feishin-player-config-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        window.activate_window();
        window.activate_accessibility_for_test();
        let mut state = fixture_state();
        state.settings.fade_on_status = false;
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        state.queue.add(
            vec![Item {
                id: "song".into(),
                name: "Song".into(),
                column_data: [("bpm".into(), "120".into())].into(),
                ..Default::default()
            }],
            Enqueue::Now,
        );
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.simulate_resize(gpui::size(px(1400.), px(1100.)));
    cx.run_until_parked();
    let original = app.read_with(cx, |app, _| {
        (
            app.route.clone(),
            app.history.clone(),
            serde_json::to_value(&app.state.queue).unwrap(),
        )
    });
    for language in ["en", "fr", "ar", "ja"] {
        cx.update(|_, cx| {
            app.update(cx, |app, cx| {
                app.state.settings.language = language.into();
                app.state.settings.transition = Mode::Gapless;
                app.state.settings.preserve_pitch = true;
                app.state.settings.microtonal_pitch_controls = false;
                app.state.settings.panels.expanded = false;
                cx.notify();
            })
        });
        cx.run_until_parked();
        click(cx, "player-configure");
        let popup = cx.debug_bounds("player-config-controls").unwrap();
        assert!(popup.origin.y >= px(0.) && popup.bottom() <= px(1100.));
        let text = |key: &str| feishin_core::i18n::translate(language, key).unwrap();
        click(cx, "player-config-crossfade");
        assert_eq!(
            app.read_with(cx, |app, _| app.state.settings.transition),
            Mode::Crossfade
        );
        let duration = text("setting.crossfadeDuration");
        let (_, duration_node) = node(cx, Role::Slider, &duration);
        assert_eq!(duration_node.min_numeric_value(), Some(3.));
        assert_eq!(duration_node.max_numeric_value(), Some(21.));
        slider(cx, &duration, 18.);
        assert_eq!(
            app.read_with(cx, |app, _| app.state.settings.crossfade_seconds),
            18.
        );
        // Mouse edits remain local until release, including release outside the slider.
        let (_, duration_node) = node(cx, Role::Slider, &duration);
        let bounds = duration_node.bounds().unwrap();
        let position = cx.update(|window, _| {
            point(
                px((if feishin_core::i18n::rtl(language) {
                    bounds.x0 / f64::from(window.scale_factor()) + 1.
                } else {
                    bounds.x1 / f64::from(window.scale_factor()) - 1.
                }) as f32),
                px(((bounds.y0 + bounds.y1) / (2. * f64::from(window.scale_factor()))) as f32),
            )
        });
        cx.simulate_mouse_down(position, MouseButton::Left, Modifiers::none());
        cx.run_until_parked();
        assert_eq!(
            app.read_with(cx, |app, _| app.state.settings.crossfade_seconds),
            18.
        );
        cx.simulate_mouse_up(
            point(px(10.), px(10.)),
            MouseButton::Left,
            Modifiers::none(),
        );
        cx.run_until_parked();
        assert_eq!(
            app.read_with(cx, |app, _| app.state.settings.crossfade_seconds),
            21.
        );
        click(cx, "player-config-curve");
        click_node(cx, Role::MenuItem, "S-Curve");
        assert_eq!(
            app.read_with(cx, |app, _| app.state.settings.crossfade_style),
            Curve::SCurve
        );
        slider(cx, &text("player.playbackSpeed"), 1.73);
        assert!(cx.update(|window, _| {
            window
                .accessibility_tree_for_test()
                .unwrap()
                .nodes
                .iter()
                .any(|(_, node)| node.value() == Some("1.73 x / 207.6 BPM"))
        }));
        assert_eq!(
            app.read_with(cx, |app, cx| app.speed_input.read(cx).value().to_string()),
            "1.73"
        );
        let speed_bounds = cx.debug_bounds("player-config-speed").unwrap();
        let position = speed_bounds.origin + point(px(4.), px(4.));
        cx.simulate_event(gpui::MouseDownEvent {
            position,
            modifiers: Modifiers::none(),
            button: MouseButton::Left,
            click_count: 2,
            first_mouse: false,
        });
        cx.simulate_event(gpui::MouseUpEvent {
            position,
            modifiers: Modifiers::none(),
            button: MouseButton::Left,
            click_count: 2,
        });
        cx.run_until_parked();
        assert_eq!(app.read_with(cx, |app, _| app.state.settings.speed), 1.);
        click_node(cx, Role::CheckBox, &text("setting.preservePitch"));
        click_node(cx, Role::Button, "+1 semitone");
        assert!(
            (app.read_with(cx, |app, _| app.state.settings.speed) - 2_f32.powf(1. / 12.)).abs()
                < 1e-6
        );
        cx.update(|_, cx| {
            app.update(cx, |app, cx| {
                app.state.settings.microtonal_pitch_controls = true;
                cx.notify();
            })
        });
        cx.run_until_parked();
        click_node(cx, Role::Button, "-10 cents");
        assert!(
            (app.read_with(cx, |app, _| app.state.settings.speed) - 2_f32.powf(0.9 / 12.)).abs()
                < 1e-6
        );
        for (index, key) in [
            "setting.showQueueInSidebar",
            "setting.showLyricsInSidebar",
            "setting.showVisualizerInSidebar",
            "setting.combinedLyricsAndVisualizer",
        ]
        .into_iter()
        .enumerate()
        {
            let before = app.read_with(cx, |app, _| {
                let p = &app.state.settings.panels;
                [p.queue, p.lyrics, p.visualizer, p.combined][index]
            });
            click_node(cx, Role::CheckBox, &text(key));
            assert_ne!(
                app.read_with(cx, |app, _| {
                    let p = &app.state.settings.panels;
                    [p.queue, p.lyrics, p.visualizer, p.combined][index]
                }),
                before
            );
        }
        cx.update(|_, cx| {
            app.update(cx, |app, cx| {
                app.playing = true;
                cx.notify();
            })
        });
        cx.run_until_parked();
        assert!(node(cx, Role::Button, "Native").1.is_disabled());
        click(cx, "player-config-engine");
        assert!(!cx.update(|window, _| {
            window
                .accessibility_tree_for_test()
                .unwrap()
                .nodes
                .iter()
                .any(|(_, node)| node.role() == Role::MenuItem)
        }));
        assert!(node(cx, Role::Slider, &duration).1.is_disabled());
        slider(cx, &duration, 3.);
        assert_eq!(
            app.read_with(cx, |app, _| app.state.settings.crossfade_seconds),
            21.
        );
        cx.update(|_, cx| {
            app.update(cx, |app, cx| {
                app.playing = false;
                cx.notify();
            })
        });
        cx.simulate_keystrokes("escape");
        cx.run_until_parked();
        assert!(!cx.update(|window, _| {
            window
                .accessibility_tree_for_test()
                .unwrap()
                .nodes
                .iter()
                .any(|(_, node)| node.role() == Role::Dialog)
        }));
        app.read_with(cx, |app, _| {
            assert_eq!(app.route, original.0);
            assert_eq!(app.history, original.1);
            assert_eq!(serde_json::to_value(&app.state.queue).unwrap(), original.2);
        });
    }
    // The selected engine retains a custom executable and independent device IDs.
    let custom = dir.join("custom-mpv").to_string_lossy().to_string();
    cx.update(|_, cx| {
        app.update(cx, |app, cx| {
            app.state.settings.mpv_path = custom.clone();
            app.state.settings.audio_device = "Native DAC".into();
            app.state.settings.mpv_audio_device = "coreaudio/42".into();
            cx.notify();
        })
    });
    cx.run_until_parked();
    click(cx, "player-configure");
    click(cx, "player-config-engine");
    click_node(cx, Role::MenuItem, "Native");
    assert!(app.read_with(cx, |app, _| app.state.settings.mpv_path.is_empty()));
    let saved = feishin_core::storage::load(&dir.join("state.json")).unwrap();
    assert_eq!(saved.settings.saved_mpv_path, custom);
    click(cx, "player-config-engine");
    click_node(cx, Role::MenuItem, "MPV");
    app.read_with(cx, |app, _| {
        assert_eq!(app.state.settings.mpv_path, custom);
        assert_eq!(app.state.settings.audio_device, "Native DAC");
        assert_eq!(app.state.settings.mpv_audio_device, "coreaudio/42");
    });
    click(cx, "player-config-device");
    click_node(
        cx,
        Role::MenuItem,
        &feishin_core::i18n::translate("ja", "setting.audioDeviceDefault").unwrap(),
    );
    assert_eq!(
        app.read_with(cx, |app, _| app.state.settings.mpv_audio_device.clone()),
        "auto"
    );
    click(cx, "player-config-reload");
    assert!(!app.read_with(cx, |app, _| app.playing || app.loaded));
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    cx.simulate_resize(gpui::size(px(960.), px(640.)));
    cx.run_until_parked();
    click(cx, "player-configure");
    let bounds = cx.debug_bounds("player-config-controls").unwrap();
    assert!(
        bounds.origin.x >= px(0.)
            && bounds.origin.y >= px(0.)
            && bounds.right() <= px(960.)
            && bounds.bottom() <= px(640.)
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    for language in ["en", "fr", "ar"] {
        cx.update(|window, cx| {
            app.update(cx, |app, cx| {
                app.route = Route::Settings;
                app.state.settings.language = language.into();
                app.state.settings.mpv_path.clear();
                app.state.settings.transition = Mode::Gapless;
                app.apply_theme(window, cx);
                app.state.settings.settings_tab = feishin_core::settings_search::Tab::Playback;
                app.settings_search.update(cx, |input, cx| {
                    input.set_value(
                        feishin_core::i18n::translate(language, "setting.crossfadeStyle").unwrap(),
                        window,
                        cx,
                    )
                });
                cx.notify();
            })
        });
        cx.run_until_parked();
        click(cx, "settings-player-configure");
        // The engine row can sit above the scrolling Settings viewport. Its
        // child menu must remain clickable, and Escape closes only that menu.
        click(cx, "player-config-engine");
        node(cx, Role::MenuItem, "Native");
        cx.simulate_keystrokes("escape");
        cx.run_until_parked();
        node(
            cx,
            Role::Dialog,
            &feishin_core::i18n::translate(language, "common.setting_other").unwrap(),
        );
        click(cx, "player-config-crossfade");
        assert_eq!(
            app.read_with(cx, |app, _| app.state.settings.transition),
            Mode::Crossfade
        );
        let duration =
            feishin_core::i18n::translate(language, "setting.crossfadeDuration").unwrap();
        slider(cx, &duration, 7.);
        assert_eq!(
            app.read_with(cx, |app, _| app.state.settings.crossfade_seconds),
            7.
        );
        let saved = feishin_core::storage::load(&dir.join("state.json")).unwrap();
        assert_eq!(saved.settings.crossfade_seconds, 7.);
        for (playing, mpv, jukebox) in [
            (true, false, false),
            (false, true, false),
            (false, false, true),
        ] {
            app.update(cx, |app, cx| {
                app.playing = playing;
                app.state.settings.mpv_path = if mpv { custom.clone() } else { String::new() };
                app.state.settings.jukebox = jukebox;
                cx.notify();
            });
            cx.run_until_parked();
            assert!(node(cx, Role::Slider, &duration).1.is_disabled());
            assert!(
                node(
                    cx,
                    Role::Button,
                    &feishin_core::i18n::translate(language, "setting.playbackStyle_optionNormal")
                        .unwrap()
                )
                .1
                .is_disabled()
            );
            slider(cx, &duration, 3.);
            click(cx, "player-config-gapless");
            app.read_with(cx, |app, _| {
                assert_eq!(app.state.settings.crossfade_seconds, 7.);
                assert_eq!(app.state.settings.transition, Mode::Crossfade);
                assert_eq!(serde_json::to_value(&app.state.queue).unwrap(), original.2);
            });
        }
        app.update(cx, |app, cx| {
            app.playing = false;
            app.state.settings.mpv_path.clear();
            app.state.settings.jukebox = false;
            cx.notify();
        });
        cx.simulate_keystrokes("escape");
        cx.run_until_parked();
        assert!(
            cx.update(|window, _| window
                .accessibility_tree_for_test()
                .unwrap()
                .nodes
                .iter()
                .all(|(_, node)| node.role() != Role::Dialog)),
            "{language}: Escape must close the player configuration"
        );
        assert_eq!(
            app.read_with(cx, |app, _| app.route.clone()),
            Route::Settings
        );
        // The playerbar entry uses a separate popover state and sees settings edits.
        click(cx, "player-configure");
        assert_eq!(
            node(cx, Role::Slider, &duration).1.numeric_value(),
            Some(7.)
        );
        cx.simulate_keystrokes("escape");
        cx.run_until_parked();
        assert!(
            cx.update(|window, _| window
                .accessibility_tree_for_test()
                .unwrap()
                .nodes
                .iter()
                .all(|(_, node)| node.role() != Role::Dialog)),
            "{language}: Escape must close the player configuration"
        );
    }
    std::fs::remove_dir_all(dir).unwrap();
}

#[gpui::test]
fn shared_play_button_hold_cancels_and_preserves_normal_activation(cx: &mut TestAppContext) {
    use gpui::{IntoElement, Modifiers, MouseButton, ParentElement, Render, Styled, px};
    use gpui_component::{Disableable, button::Button};
    use std::time::Duration;

    #[derive(Default)]
    struct Probe {
        actions: Vec<&'static str>,
        disabled: bool,
        loading: bool,
        hidden: bool,
        hold_only: bool,
    }
    impl Render for Probe {
        fn render(
            &mut self,
            _: &mut gpui::Window,
            cx: &mut gpui::Context<Self>,
        ) -> impl IntoElement {
            use gpui::InteractiveElement;
            use gpui::prelude::FluentBuilder;
            gpui::div().size_full().p_4().when(!self.hidden, |div| {
                div.child(
                    Button::new("hold-probe")
                        .long_press_feedback(gpui::rgb(0xf04173).into())
                        .w(px(48.))
                        .h(px(48.))
                        .border_0()
                        .debug_selector(|| "hold-probe".into())
                        .label("Play")
                        .disabled(self.disabled)
                        .loading(self.loading)
                        .when(!self.hold_only, |button| {
                            button.on_click(cx.listener(|view, _, _, cx| {
                                view.actions.push("click");
                                cx.notify();
                            }))
                        })
                        .on_long_press(cx.listener(|view, _, _, cx| {
                            view.actions.push("hold");
                            cx.notify();
                        })),
                )
            })
        }
    }
    cx.update(gpui_component::init);
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let view = cx.new(|_| Probe::default());
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let probe = captured.borrow_mut().take().unwrap();
    cx.run_until_parked();
    let position = cx.debug_bounds("hold-probe").unwrap().center();
    let outside = gpui::point(px(400.), px(300.));
    let has_feedback = |cx: &mut gpui::VisualTestContext| {
        let color: gpui::Hsla = gpui::rgb(0xf04173).into();
        cx.update(|window, _| window.painted_lines_and_quads_for_test())
            .iter()
            .any(|(_, actual, _, _)| {
                actual.h == color.h && actual.s == color.s && actual.l == color.l
            })
    };
    cx.simulate_click(position, Modifiers::none());
    cx.run_until_parked();
    probe.read_with(cx, |view, _| assert_eq!(view.actions, ["click"]));
    cx.executor().advance_clock(Duration::from_millis(600));
    cx.run_until_parked();
    probe.read_with(cx, |view, _| assert_eq!(view.actions, ["click"]));

    cx.simulate_mouse_down(position, MouseButton::Left, Modifiers::none());
    cx.run_until_parked();
    let references: Vec<serde_json::Value> = serde_json::from_str(include_str!(
        "../assets/play-button-animation-reference.json"
    ))
    .unwrap();
    let mut previous = 0;
    let original_bounds = cx.debug_bounds("hold-probe").unwrap();
    let display_scale = cx.update(|window, _| f64::from(window.scale_factor()));
    for reference in references {
        let milliseconds = reference["milliseconds"].as_u64().unwrap();
        cx.executor()
            .advance_clock(Duration::from_millis(milliseconds - previous));
        previous = milliseconds;
        if milliseconds == 499 {
            cx.simulate_mouse_move(
                position + gpui::point(px(1.), px(0.)),
                MouseButton::Left,
                Modifiers::none(),
            );
            cx.update(|_, cx| probe.update(cx, |_, cx| cx.notify()));
        }
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        let color: gpui::Hsla = gpui::rgb(0xf04173).into();
        let painted = cx.update(|window, _| window.painted_lines_and_quads_for_test());
        let circle = painted.into_iter().find(|(_, actual, _, _)| {
            actual.h == color.h && actual.s == color.s && actual.l == color.l
        });
        let scale = reference["scale"].as_f64().unwrap() as f32;
        if scale == 0. {
            assert!(circle.is_none(), "{reference}");
        } else {
            let (bounds, actual, rounded, _) = circle.unwrap_or_else(|| panic!("{reference}"));
            assert!(rounded);
            assert!(
                (f64::from(bounds.size.width)
                    / (f64::from(original_bounds.size.width) * display_scale)
                    - f64::from(scale))
                .abs()
                    < 0.00001,
                "{reference}: {bounds:?}"
            );
            assert!(
                (actual.a - reference["opacity"].as_f64().unwrap() as f32).abs() < 0.00001,
                "{reference}: {actual:?}"
            );
        }
        probe.read_with(cx, |view, _| {
            assert_eq!(
                view.actions,
                if milliseconds < 500 {
                    vec!["click"]
                } else {
                    vec!["click", "hold"]
                }
            );
        });
    }
    probe.read_with(cx, |view, _| assert_eq!(view.actions, ["click", "hold"]));
    cx.executor().advance_clock(Duration::from_secs(1));
    cx.run_until_parked();
    cx.simulate_mouse_up(position, MouseButton::Left, Modifiers::none());
    cx.run_until_parked();
    assert!(!has_feedback(cx));
    probe.read_with(cx, |view, _| assert_eq!(view.actions, ["click", "hold"]));

    cx.simulate_mouse_down(position, MouseButton::Left, Modifiers::none());
    cx.simulate_mouse_move(outside, MouseButton::Left, Modifiers::none());
    cx.run_until_parked();
    assert!(!has_feedback(cx));
    cx.simulate_mouse_move(position, MouseButton::Left, Modifiers::none());
    cx.executor().advance_clock(Duration::from_millis(600));
    cx.run_until_parked();
    cx.simulate_mouse_up(position, MouseButton::Left, Modifiers::none());
    cx.run_until_parked();
    probe.read_with(cx, |view, _| assert_eq!(view.actions, ["click", "hold"]));

    for mode in ["disabled", "loading", "hidden"] {
        cx.simulate_mouse_down(position, MouseButton::Left, Modifiers::none());
        cx.run_until_parked();
        cx.update(|_, cx| {
            probe.update(cx, |view, cx| {
                view.disabled = mode == "disabled";
                view.loading = mode == "loading";
                view.hidden = mode == "hidden";
                cx.notify();
            })
        });
        cx.run_until_parked();
        cx.executor().advance_clock(Duration::from_millis(600));
        cx.run_until_parked();
        cx.simulate_mouse_up(outside, MouseButton::Left, Modifiers::none());
        cx.run_until_parked();
        probe.read_with(cx, |view, _| {
            assert_eq!(view.actions, ["click", "hold"], "{mode}")
        });
        cx.update(|_, cx| {
            probe.update(cx, |view, cx| {
                view.disabled = false;
                view.loading = false;
                view.hidden = false;
                cx.notify();
            })
        });
        cx.run_until_parked();
    }
    cx.simulate_mouse_down(position, MouseButton::Right, Modifiers::none());
    cx.executor().advance_clock(Duration::from_millis(600));
    cx.run_until_parked();
    cx.simulate_mouse_up(position, MouseButton::Right, Modifiers::none());
    cx.run_until_parked();
    probe.read_with(cx, |view, _| assert_eq!(view.actions, ["click", "hold"]));
    cx.update(|window, _| window.focus_next());
    cx.run_until_parked();
    for key in ["enter", "space"] {
        cx.simulate_keystrokes(key);
        cx.simulate_event(gpui::KeyUpEvent {
            keystroke: gpui::Keystroke::parse(key).unwrap(),
        });
        cx.run_until_parked();
    }
    cx.run_until_parked();
    probe.read_with(cx, |view, _| {
        assert_eq!(view.actions, ["click", "hold", "click", "click"])
    });
    cx.executor().advance_clock(Duration::from_millis(600));
    cx.run_until_parked();
    probe.read_with(cx, |view, _| assert_eq!(view.actions.len(), 4));
    cx.update(|_, cx| {
        probe.update(cx, |view, cx| {
            view.hold_only = true;
            cx.notify();
        })
    });
    cx.run_until_parked();
    cx.simulate_click(position, Modifiers::none());
    cx.executor().advance_clock(Duration::from_millis(600));
    cx.run_until_parked();
    assert!(!has_feedback(cx));
    probe.read_with(cx, |view, _| assert_eq!(view.actions.len(), 4));
    cx.simulate_mouse_down(position, MouseButton::Left, Modifiers::none());
    cx.executor().advance_clock(Duration::from_millis(500));
    cx.run_until_parked();
    cx.simulate_mouse_up(position, MouseButton::Left, Modifiers::none());
    cx.run_until_parked();
    assert!(!has_feedback(cx));
    probe.read_with(cx, |view, _| assert_eq!(view.actions.last(), Some(&"hold")));
}

#[gpui::test]
fn shared_play_control_scale_matches_original_transitions(cx: &mut TestAppContext) {
    use gpui::{IntoElement, Modifiers, MouseButton, ParentElement, Render, Styled, point, px};
    use std::time::Duration;
    #[derive(Default)]
    struct Probe {
        clicks: usize,
        disabled: bool,
        loading: bool,
    }
    impl Render for Probe {
        fn render(
            &mut self,
            _: &mut gpui::Window,
            cx: &mut gpui::Context<Self>,
        ) -> impl IntoElement {
            use gpui_component::Disableable;
            gpui::div()
                .size_full()
                .bg(gpui::black())
                .p_4()
                .flex()
                .gap_3()
                .items_start()
                .children(
                    [
                        ("scale-primary", Enqueue::Now),
                        ("scale-secondary", Enqueue::Next),
                    ]
                    .map(|(id, mode)| {
                        crate::styles::play_control(id, mode, 1., cx)
                            .disabled(self.disabled)
                            .loading(self.loading)
                            .on_click(cx.listener(|view, _, _, cx| {
                                view.clicks += 1;
                                cx.notify();
                            }))
                    }),
                )
        }
    }
    cx.set_assets(crate::icons::Assets);
    cx.update(gpui_component::init);
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        window.activate_accessibility_for_test();
        let probe = cx.new(|_| Probe::default());
        captured.replace(Some(probe.clone()));
        Root::new(probe, window, cx)
    });
    let probe = captured.borrow_mut().take().unwrap();
    cx.run_until_parked();
    let reference: serde_json::Value = serde_json::from_str(include_str!(
        "../assets/play-button-interactions-reference.json"
    ))
    .unwrap();
    let outside = point(px(400.), px(300.));
    let display_scale = cx.update(|window, _| window.scale_factor());
    let original = [
        cx.debug_bounds("scale-primary").unwrap(),
        cx.debug_bounds("scale-secondary").unwrap(),
    ];
    let icons = cx.update(|window, _| window.painted_glyphs_for_test());
    assert_eq!(icons.len(), 2, "Real embedded play icons must paint");
    for frame in reference["frames"].as_array().unwrap() {
        let secondary = frame["secondary"].as_bool().unwrap();
        let index = usize::from(secondary);
        let id = if secondary {
            "scale-secondary"
        } else {
            "scale-primary"
        };
        let bounds = original[index];
        match frame["name"].as_str().unwrap() {
            "hover" => cx.simulate_mouse_move(bounds.center(), None, Modifiers::none()),
            "active" => {
                cx.simulate_mouse_down(bounds.center(), MouseButton::Left, Modifiers::none())
            }
            "release" => {
                cx.simulate_mouse_up(bounds.center(), MouseButton::Left, Modifiers::none())
            }
            "leave" => cx.simulate_mouse_move(outside, None, Modifiers::none()),
            _ => unreachable!(),
        }
        cx.run_until_parked();
        let mut previous = 0;
        for sample in frame["samples"].as_array().unwrap() {
            let ms = sample["milliseconds"].as_u64().unwrap();
            cx.executor()
                .advance_clock(Duration::from_millis(ms - previous));
            previous = ms;
            cx.update(|window, _| window.refresh());
            cx.run_until_parked();
            assert_eq!(
                cx.debug_bounds(id).unwrap(),
                bounds,
                "Hover must preserve layout"
            );
            assert_eq!(
                cx.debug_bounds(if secondary {
                    "scale-primary"
                } else {
                    "scale-secondary"
                })
                .unwrap(),
                original[1 - index],
                "Neighbor must stay fixed"
            );
            let circles = cx.update(|window, _| window.painted_lines_and_quads_for_test());
            let circle = circles
                .iter()
                .find(|(actual, color, rounded, _)| {
                    *rounded
                        && color.l == 1.
                        && ((f64::from(actual.center().x) as f32) / display_scale
                            - f32::from(bounds.center().x))
                        .abs()
                            < 0.001
                        && ((f64::from(actual.center().y) as f32) / display_scale
                            - f32::from(bounds.center().y))
                        .abs()
                            < 0.001
                })
                .unwrap_or_else(|| panic!("Missing play circle: {id}, {sample}: {circles:?}"));
            let scale = (f64::from(circle.0.size.width) as f32)
                / display_scale
                / f32::from(bounds.size.width);
            assert!(
                (f64::from(scale) - sample["scale"].as_f64().unwrap()).abs() < 0.00001,
                "{id} {} {sample}: {scale}",
                frame["name"]
            );
            let actual_icons = cx.update(|window, _| window.painted_glyphs_for_test());
            let icon = actual_icons[index].0;
            assert!(
                (f32::from(icon.size.width) / f32::from(icons[index].0.size.width) - scale).abs()
                    < 0.00001,
                "Icon must scale with circle"
            );
            assert!(
                (f32::from(icon.center().x) - f32::from(icons[index].0.center().x)).abs() < 0.001
            );
            let tree = cx
                .update(|window, _| window.accessibility_tree_for_test().cloned())
                .unwrap();
            let label = if secondary { "Next" } else { "Play" };
            let ax = tree
                .nodes
                .iter()
                .find(|(_, node)| {
                    node.role() == gpui::accesskit::Role::Button
                        && node.label().is_some_and(|value| value.starts_with(label))
                })
                .unwrap()
                .1
                .bounds()
                .unwrap();
            assert!(
                ((ax.x1 - ax.x0) as f32 / display_scale - f32::from(bounds.size.width) * scale)
                    .abs()
                    < 0.001,
                "Accessibility bounds must follow painting"
            );
        }
    }
    let mut expected_clicks = 2;
    for case in reference["interruptions"].as_array().unwrap() {
        cx.simulate_mouse_up(outside, MouseButton::Left, Modifiers::none());
        cx.simulate_mouse_move(outside, None, Modifiers::none());
        cx.run_until_parked();
        cx.executor().advance_clock(Duration::from_millis(250));
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        let index = usize::from(case["secondary"].as_bool().unwrap());
        let bounds = original[index];
        let mode = case["mode"].as_str().unwrap();
        cx.simulate_mouse_move(bounds.center(), None, Modifiers::none());
        cx.run_until_parked();
        if mode == "active-release" {
            cx.executor().advance_clock(Duration::from_millis(250));
            cx.update(|window, _| window.refresh());
            cx.run_until_parked();
            cx.simulate_mouse_down(bounds.center(), MouseButton::Left, Modifiers::none());
            cx.run_until_parked();
        }
        cx.executor()
            .advance_clock(Duration::from_millis(case["interruptAt"].as_u64().unwrap()));
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        match mode {
            "hover-leave" => cx.simulate_mouse_move(outside, None, Modifiers::none()),
            "active-release" => {
                cx.simulate_mouse_up(bounds.center(), MouseButton::Left, Modifiers::none());
                expected_clicks += 1;
            }
            "hover-active" => {
                cx.simulate_mouse_down(bounds.center(), MouseButton::Left, Modifiers::none())
            }
            _ => unreachable!(),
        }
        cx.run_until_parked();
        let mut previous = 0;
        for sample in case["samples"].as_array().unwrap() {
            let ms = sample["milliseconds"].as_u64().unwrap();
            cx.executor()
                .advance_clock(Duration::from_millis(ms - previous));
            previous = ms;
            cx.update(|window, _| window.refresh());
            cx.run_until_parked();
            let circles = cx.update(|window, _| window.painted_lines_and_quads_for_test());
            let circle = circles
                .iter()
                .find(|(actual, color, rounded, _)| {
                    *rounded
                        && color.l == 1.
                        && (f64::from(actual.center().x) / f64::from(display_scale)
                            - f64::from(bounds.center().x))
                        .abs()
                            < 0.001
                        && (f64::from(actual.center().y) / f64::from(display_scale)
                            - f64::from(bounds.center().y))
                        .abs()
                            < 0.001
                })
                .unwrap();
            let scale = f64::from(circle.0.size.width)
                / f64::from(display_scale)
                / f64::from(bounds.size.width);
            assert!(
                (scale - sample["scale"].as_f64().unwrap()).abs() < 0.00001,
                "Interrupted original {case}, sample {sample}: {scale}"
            );
            assert_eq!(
                cx.debug_bounds(if index == 0 {
                    "scale-primary"
                } else {
                    "scale-secondary"
                })
                .unwrap(),
                bounds
            );
        }
    }
    cx.simulate_mouse_up(outside, MouseButton::Left, Modifiers::none());
    cx.simulate_mouse_move(outside, None, Modifiers::none());
    cx.run_until_parked();
    cx.executor().advance_clock(Duration::from_millis(250));
    cx.update(|window, _| window.refresh());
    cx.run_until_parked();
    probe.read_with(cx, |view, _| assert_eq!(view.clicks, expected_clicks));
    let bounds = original[0];
    cx.simulate_mouse_move(bounds.center(), None, Modifiers::none());
    cx.run_until_parked();
    cx.executor().advance_clock(Duration::from_millis(200));
    cx.update(|window, _| window.refresh());
    cx.run_until_parked();
    let expanded_edge = point(bounds.right() + px(1.), bounds.center().y);
    cx.simulate_mouse_move(expanded_edge, None, Modifiers::none());
    cx.simulate_click(expanded_edge, Modifiers::none());
    cx.run_until_parked();
    probe.read_with(cx, |view, _| {
        assert_eq!(
            view.clicks,
            expected_clicks + 1,
            "Expanded painted area must accept clicks"
        )
    });
    for loading in [false, true] {
        cx.update(|_, cx| {
            probe.update(cx, |view, cx| {
                view.disabled = !loading;
                view.loading = loading;
                cx.notify();
            })
        });
        cx.run_until_parked();
        cx.simulate_click(bounds.center(), Modifiers::none());
        cx.executor().advance_clock(Duration::from_millis(250));
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        probe.read_with(cx, |view, _| assert_eq!(view.clicks, expected_clicks + 1));
    }
    cx.simulate_mouse_move(outside, None, Modifiers::none());
    for reference in reference["states"].as_array().unwrap() {
        let class = reference["className"].as_str().unwrap();
        cx.update(|_, cx| {
            probe.update(cx, |view, cx| {
                view.disabled = class == "disabled";
                view.loading = class == "loading";
                cx.notify();
            })
        });
        cx.run_until_parked();
        cx.executor().advance_clock(Duration::from_millis(250));
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        let index = usize::from(reference["secondary"].as_bool().unwrap());
        let base = original[index];
        let offset = point(
            px(reference["x"].as_f64().unwrap() as f32),
            px(reference["y"].as_f64().unwrap() as f32),
        );
        let expected_center = (base.center() + offset).scale(display_scale);
        let circles = cx.update(|window, _| window.painted_lines_and_quads_for_test());
        let circle = circles
            .iter()
            .find(|(bounds, color, rounded, _)| {
                *rounded
                    && color.l == 1.
                    && f64::from(bounds.center().x - expected_center.x).abs() < 0.001
                    && f64::from(bounds.center().y - expected_center.y).abs() < 0.001
            })
            .unwrap_or_else(|| panic!("Original state geometry: {reference}: {circles:?}"));
        assert_eq!(circle.0.size, base.size.scale(display_scale));
        #[cfg(any(target_os = "macos", target_os = "linux", target_os = "freebsd"))]
        {
            // Paint the production scene into a windowless GPU texture. The black
            // probe background makes the original half-opacity white circle measurable.
            let viewport = gpui::size(px(160.), px(120.));
            let rgba = cx
                .update(|window, _| window.rasterized_scene_for_test(viewport))
                .unwrap();
            let point = (base.center() + offset + point(base.size.width * 0.4, px(0.)))
                .scale(display_scale);
            let x = f64::from(point.x).floor() as usize;
            let y = f64::from(point.y).floor() as usize;
            let width = (f32::from(viewport.width) * display_scale).round() as usize;
            let pixel = &rgba[(y * width + x) * 4..][..4];
            let channel = (reference["opacity"].as_f64().unwrap() * 255.).round() as i32;
            assert!(
                pixel[..3]
                    .iter()
                    .all(|value| (i32::from(*value) - channel).abs() <= 1),
                "Original opacity: {reference}: {pixel:?}"
            );
            assert_eq!(pixel[3], 255);
        }
    }
}

#[gpui::test]
fn shared_play_loading_matches_original_spinner(cx: &mut TestAppContext) {
    use gpui::{IntoElement, ParentElement, Render, Styled, px};
    use gpui_component::{ActiveTheme, Theme};
    use std::time::Duration;
    struct Probe {
        zoom: f32,
        loading: bool,
    }
    impl Render for Probe {
        fn render(
            &mut self,
            _: &mut gpui::Window,
            cx: &mut gpui::Context<Self>,
        ) -> impl IntoElement {
            gpui::div()
                .size_full()
                .p_4()
                .flex()
                .gap_3()
                .items_start()
                .children(
                    [
                        ("loading-primary", Enqueue::Now),
                        ("loading-secondary", Enqueue::Next),
                    ]
                    .map(|(id, mode)| {
                        crate::styles::play_control(id, mode, self.zoom, cx).loading(self.loading)
                    }),
                )
        }
    }
    cx.set_assets(crate::icons::Assets);
    cx.update(gpui_component::init);
    let reference: Vec<serde_json::Value> =
        serde_json::from_str(include_str!("../assets/spinner-animation-reference.json")).unwrap();
    for font_size in [18., 27., 23.] {
        let zoom = if font_size == 27. { 1.5 } else { 1. };
        cx.update(|cx| {
            Theme::global_mut(cx).font_size = px(16. * zoom);
            let mut css = crate::styles::icon_stylesheet();
            if font_size == 23. {
                css.push_str("\n:root {--theme-font-size-xl:23px}");
            }
            let sheet = feishin_core::styles::Stylesheet::parse([css.as_str()]).unwrap();
            cx.set_global(crate::styles::NativeStyles::new(
                sheet,
                feishin_core::appearance::Palette::default(),
            ));
        });
        let captured = Rc::new(RefCell::new(None));
        let (_, cx) = cx.add_window_view(|window, cx| {
            window.set_rem_size(cx.theme().font_size);
            let probe = cx.new(|_| Probe {
                zoom,
                loading: true,
            });
            captured.replace(Some(probe.clone()));
            Root::new(probe, window, cx)
        });
        let probe = captured.borrow_mut().take().unwrap();
        cx.run_until_parked();
        let bounds = [
            cx.debug_bounds("loading-primary").unwrap(),
            cx.debug_bounds("loading-secondary").unwrap(),
        ];
        assert_eq!(f32::from(bounds[0].size.width), 48. * zoom);
        assert_eq!(f32::from(bounds[1].size.width), 32. * zoom);
        let mut previous = 0;
        for sample in reference
            .iter()
            .filter(|row| row["fontSize"].as_f64() == Some(font_size))
        {
            let milliseconds = sample["milliseconds"].as_u64().unwrap();
            cx.executor()
                .advance_clock(Duration::from_millis(milliseconds - previous));
            previous = milliseconds;
            cx.update(|window, _| window.refresh());
            cx.run_until_parked();
            let glyphs = cx.update(|window, _| window.painted_glyphs_for_test());
            let matrices = cx.update(|window, _| window.painted_glyph_transforms_for_test());
            assert_eq!(
                glyphs.len(),
                2,
                "Loading must replace each play icon: {sample}"
            );
            for (index, (actual, _, _)) in glyphs.iter().enumerate() {
                assert!(
                    (f64::from(actual.size.width) - sample["width"].as_f64().unwrap()).abs()
                        < 0.0001,
                    "Spinner width: {sample}: {actual:?}"
                );
                assert!(
                    (f64::from(actual.size.height) - sample["height"].as_f64().unwrap()).abs()
                        < 0.0001,
                    "Spinner height: {sample}: {actual:?}"
                );
                assert!((actual.center().x - bounds[index].center().x).abs() < px(0.0001));
                assert!((actual.center().y - bounds[index].center().y).abs() < px(0.0001));
                let [[a, c], [b, d]] = matrices[index];
                for (value, expected) in [a, b, c, d]
                    .into_iter()
                    .zip(sample["matrix"].as_array().unwrap())
                {
                    assert!(
                        (f64::from(value) - expected.as_f64().unwrap()).abs() < 0.000002,
                        "Spinner rotation: {sample}: {matrices:?}"
                    );
                }
                assert_eq!(
                    cx.debug_bounds(if index == 0 {
                        "loading-primary"
                    } else {
                        "loading-secondary"
                    })
                    .unwrap(),
                    bounds[index]
                );
            }
        }
        cx.update(|_, cx| {
            probe.update(cx, |view, cx| {
                view.loading = false;
                cx.notify();
            })
        });
        cx.run_until_parked();
        let glyphs = cx.update(|window, _| window.painted_glyphs_for_test());
        assert_eq!(glyphs.len(), 2);
        for (index, (glyph, _, _)) in glyphs.iter().enumerate() {
            assert_eq!(glyph.size.width, px(16. * zoom));
            assert!((glyph.center().x - bounds[index].center().x).abs() < px(0.0001));
        }
    }
}

#[gpui::test]
fn content_badges_reach_tables_cards_and_duplicate_safe_queues(cx: &mut TestAppContext) {
    use gpui_component::ActiveTheme;
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!("feishin-content-badges-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(fixture_state()), window, cx));
        window.activate_accessibility_for_test();
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.update(|_, cx| {
        let style = crate::ui::content_mark_style(cx);
        let size = style.text.as_ref().unwrap().font_size.unwrap();
        assert_eq!(size.to_pixels(cx.theme().font_size), cx.theme().font_size);
        assert_eq!(
            style
                .padding
                .right
                .unwrap()
                .to_pixels(size, cx.theme().font_size),
            cx.theme().font_size * 0.25
        );
        assert_eq!(style.text.unwrap().font_family.unwrap().as_ref(), "Symbola");
    });
    let items = ["e", "EXPLICIT", "c", "CLEAN", "unknown", ""]
        .into_iter()
        .enumerate()
        .map(|(index, status)| {
            let mut item = Item {
                id: format!("status-{index}"),
                name: format!("Content {index}"),
                kind: ItemKind::Album,
                ..Default::default()
            };
            item.column_data
                .insert("explicitStatus".into(), status.into());
            item
        })
        .chain(std::iter::once(Item {
            id: "artist".into(),
            name: "Artist".into(),
            kind: ItemKind::Artist,
            column_data: [("explicitStatus".into(), "e".into())].into(),
            ..Default::default()
        }))
        .collect::<Vec<_>>();
    for display in ["table", "poster", "queue"] {
        cx.update(|_, cx| {
            app.update(cx, |view, cx| {
                view.items = items.clone();
                view.state.settings.home.items.clear();
                view.state.settings.home.feature = false;
                view.route = Route::Library(ItemKind::Album);
                let mut config = feishin_core::lists::default_for("album");
                if display == "queue" {
                    view.state.queue = Default::default();
                    view.state.queue.add(
                        items
                            .iter()
                            .filter(|item| item.kind == ItemKind::Album)
                            .map(|item| Item {
                                kind: ItemKind::Song,
                                ..item.clone()
                            })
                            .collect(),
                        Enqueue::End,
                    );
                    view.route = Route::Queue;
                } else {
                    config.display = display.into();
                    view.state.settings.lists.insert("album".into(), config);
                }
                cx.notify();
            })
        });
        cx.refresh().unwrap();
        cx.run_until_parked();
        let tree = cx.update(|window, _| window.accessibility_tree_for_test().unwrap().clone());
        for label in ["Explicit", "Clean"] {
            assert_eq!(
                tree.nodes
                    .iter()
                    .filter(
                        |(_, node)| node.role() == gpui::Role::Label && node.label() == Some(label)
                    )
                    .count(),
                2,
                "{display}: {label}"
            );
        }
    }
    let _ = std::fs::remove_dir_all(dir);
}

#[gpui::test]
fn detail_metadata_navigation_mouse_refresh_and_stale_results_preserve_local_edits(
    cx: &mut TestAppContext,
) {
    use feishin_core::{
        api::Api,
        model::{Server, ServerType, Session},
    };
    use serde_json::json;
    use std::{
        io::{BufRead, BufReader, Write},
        net::TcpListener,
        sync::{
            Arc,
            atomic::{AtomicBool, AtomicUsize, Ordering},
        },
        thread,
        time::{Duration, Instant},
    };
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    listener.set_nonblocking(true).unwrap();
    let server = Server {
        id: uuid::Uuid::new_v4(),
        name: "Detail fixture".into(),
        url: format!("http://{}", listener.local_addr().unwrap()),
        username: "fixture".into(),
        kind: ServerType::Navidrome,
        legacy_auth: false,
        options: Default::default(),
    };
    let done = Arc::new(AtomicBool::new(false));
    let requests = Arc::new(AtomicUsize::new(0));
    let stop = done.clone();
    let calls = requests.clone();
    let fixture = thread::spawn(move || {
        while !stop.load(Ordering::Relaxed) {
            let Ok((mut socket, _)) = listener.accept() else {
                thread::sleep(Duration::from_millis(2));
                continue;
            };
            socket.set_nonblocking(false).unwrap();
            socket
                .set_read_timeout(Some(Duration::from_secs(2)))
                .unwrap();
            let mut reader = BufReader::new(socket.try_clone().unwrap());
            let mut first = String::new();
            reader.read_line(&mut first).unwrap();
            loop {
                let mut line = String::new();
                reader.read_line(&mut line).unwrap();
                if line == "\r\n" || line.is_empty() {
                    break;
                }
            }
            let path = first.split_whitespace().nth(1).unwrap();
            let body = if path.split('?').next() == Some("/api/album/album") {
                let index = calls.fetch_add(1, Ordering::Relaxed) + 1;
                json!({"id":"album", "name":format!("Full album {index}"),
                    "comment":"Full metadata", "year":2024, "minYear":2024, "maxYear":2024, "songCount":2,
                    "duration":30, "participants":{"albumartist":[{"id":"artist","name":"Artist"}]},
                    "tags":{"recordlabel":["Studio 42"],"grouping":["Series"],"mood":["Joyful"]},
                    "discs":{"1":"Original", "2":"Bonus"},
                    "genres":[{"id":"rock","name":"Rock"},{"id":"pop","name":"Pop"},{"id":"ignored","name":"Third genre"}]})
            } else if path.starts_with("/api/song?") {
                json!([
                    {"id":"song-a","title":"Track A","albumId":"album","discNumber":1,"trackNumber":1},
                    {"id":"song-b","title":"Track B","albumId":"album","discNumber":1,"trackNumber":2},
                    {"id":"song-c","title":"Track C","albumId":"album","discNumber":2,"trackNumber":1}
                ])
            } else if path.starts_with("/api/album?") {
                if path.contains("_start=20") {
                    json!([{"id":"related-20","name":"Next page A"},{"id":"related-21","name":"Next page B"}])
                } else {
                    let mut albums = vec![json!({"id":"album","name":"Excluded current album"})];
                    albums.extend((1..20).map(|index| json!({"id":format!("related-{index}"),"name":format!("Related {index}")})));
                    json!(albums)
                }
            } else {
                json!([])
            }
            .to_string();
            let status = if path.contains("getCoverArt") {
                "404 Not Found"
            } else {
                "200 OK"
            };
            write!(socket, "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}", body.len()).unwrap();
        }
    });
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!("feishin-detail-ui-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.simulate_resize(gpui::size(gpui::px(1200.), gpui::px(1000.)));
    cx.run_until_parked();
    let original = Item {
        id: "album".into(),
        name: "Summary album".into(),
        kind: ItemKind::Album,
        server_id: server.id,
        ..Default::default()
    };
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.state.active_server = Some(server.id);
            view.state.servers.push(server.clone());
            view.sessions.insert(
                server.id,
                Api::new(server.clone(), Session::default()).unwrap(),
            );
            view.state.queue.add(
                vec![Item {
                    id: "preserved".into(),
                    ..Default::default()
                }],
                Enqueue::End,
            );
            view.lyrics = feishin_core::lyrics::parse_lrc("[00:00.00]Preserved lyrics");
            view.navigate(Route::Detail(Box::new(original.clone())), cx);
        })
    });
    for expected in [1, 2] {
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            cx.run_until_parked();
            let ready = app.read_with(cx, |view, _| {
                !view.loading
                    && view.album_related.len() == 3
                    && view
                        .album_related
                        .iter()
                        .all(|section| !section.state.loading)
                    && matches!(&view.route,
                Route::Detail(item) if item.name == format!("Full album {expected}"))
            });
            if ready {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "Full detail metadata did not arrive"
            );
            thread::sleep(Duration::from_millis(5));
        }
        if expected == 1 {
            // Album headers match the original layout, which has no standalone
            // refresh button. Reload remains available through the native menu.
            cx.dispatch_action(crate::app_menu::RunMenu {
                command: crate::app_menu::Command::Reload,
            });
        }
    }
    assert_eq!(requests.load(Ordering::Relaxed), 2);
    let header = cx.debug_bounds("library-detail-header").unwrap();
    for selector in [
        "detail-header-metadata-songCount",
        "detail-header-metadata-duration",
        "detail-header-artists",
    ] {
        let value = cx.debug_bounds(selector).unwrap();
        assert!(
            value.origin.y >= header.origin.y && value.bottom() <= header.bottom(),
            "{selector} must remain in the header"
        );
    }
    for width in [1700., 1200.] {
        cx.simulate_resize(gpui::size(gpui::px(width), gpui::px(1000.)));
        cx.run_until_parked();
        app.update(cx, |view, cx| {
            view.album_details_scroll.scroll_to(gpui::ListOffset {
                item_ix: 1,
                offset_in_item: gpui::px(0.),
            });
            cx.notify();
        });
        cx.run_until_parked();
        let metadata = cx.debug_bounds("album-metadata").unwrap();
        let controls = cx.debug_bounds("library-track-controls").unwrap();
        if width > 1600. {
            assert!((f32::from(metadata.size.width) - 300.).abs() < 1.);
            assert!(
                controls.right() <= metadata.left(),
                "{controls:?} overlaps {metadata:?}"
            );
            let before = app.read_with(cx, |view, _| {
                view.album_details_scroll.scroll_px_offset_for_scrollbar().y
            });
            cx.simulate_event(gpui::ScrollWheelEvent {
                position: metadata.center(),
                delta: gpui::ScrollDelta::Pixels(gpui::point(gpui::px(0.), gpui::px(-180.))),
                modifiers: gpui::Modifiers::none(),
                touch_phase: gpui::TouchPhase::Moved,
            });
            cx.run_until_parked();
            assert!(
                app.read_with(cx, |view, _| view
                    .album_details_scroll
                    .scroll_px_offset_for_scrollbar()
                    .y)
                    < before
            );
        } else {
            assert!(
                metadata.bottom() <= controls.top(),
                "{metadata:?} must precede {controls:?}"
            );
        }
    }
    app.read_with(cx, |view, _| {
        assert_eq!(view.items.len(), 3);
        assert_eq!(view.album_related.len(), 3);
        assert_eq!(view.album_related[0].query.filters.artist_ids, ["artist"]);
        assert_eq!(view.album_related[1].query.filters.genre_ids, ["rock"]);
        assert_eq!(view.album_related[2].query.filters.genre_ids, ["pop"]);
        assert!(
            view.album_related
                .iter()
                .all(|section| section.state.items.len() == 19
                    && section.state.offset == 20
                    && section.state.items.iter().all(|item| item.id != "album"))
        );
    });
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.selected.insert(2);
            view.album_details_scroll
                .scroll_to_reveal_item(view.detail_row_position(0).unwrap() - 1);
            cx.notify();
        })
    });
    cx.run_until_parked();
    for expected in [vec![0, 1, 2], vec![2]] {
        let disc = cx.debug_bounds("album-disc-select-1").unwrap().center();
        cx.simulate_click(disc, gpui::Modifiers::none());
        cx.run_until_parked();
        app.read_with(cx, |view, _| {
            let mut selected = view.selected.iter().copied().collect::<Vec<_>>();
            selected.sort_unstable();
            assert_eq!(selected, expected);
        });
    }
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.album_details_scroll.scroll_to(gpui::ListOffset {
                item_ix: 1 + view
                    .album_page_rows(1)
                    .iter()
                    .position(|row| matches!(row, crate::details::AlbumPageRow::Related(1)))
                    .unwrap(),
                offset_in_item: gpui::px(0.),
            });
            cx.notify();
        })
    });
    cx.run_until_parked();
    let next = cx.debug_bounds("album-related-next-1").unwrap().center();
    assert!(
        next.x < gpui::px(1200.) && next.y < gpui::px(1000.),
        "Related pager is outside the viewport: {next:?}"
    );
    let columns = app.read_with(cx, |view, _| {
        crate::grid_carousel::columns(
            view.album_related[1].state.grid.borrow().width / view.state.settings.zoom,
        )
    });
    let target_page = 19 / columns;
    for _ in 0..target_page {
        cx.simulate_click(next, gpui::Modifiers::none());
        cx.run_until_parked();
    }
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        cx.run_until_parked();
        if app.read_with(cx, |view, _| {
            view.album_related[1].state.grid.borrow().carousel.page == target_page
                && view.album_related[1].state.items.len() == 21
        }) {
            break;
        }
        assert!(
            Instant::now() < deadline,
            "Related album page did not arrive: {:?}",
            app.read_with(cx, |view, _| {
                let state = &view.album_related[1].state;
                (
                    state.grid.borrow().carousel.page,
                    state.items.len(),
                    state.offset,
                    state.loading,
                    state.has_more,
                    state.error.clone(),
                )
            })
        );
        thread::sleep(Duration::from_millis(5));
    }
    cx.update(|_, cx| app.update(cx, |view, cx| {
        let generation = view.album_tracks_generation;
        let Route::Detail(current) = &mut view.route else { panic!() };
        assert_eq!((current.year, current.comment.as_str()), (2024,"Full metadata"));
        let request = current.as_ref().clone();
        current.favorite = true;
        current.rating = 5;
        let mut full = request.clone();
        full.comment = "Updated metadata".into();
        view.receive_detail_metadata(generation, &request, Ok(full.clone()), cx);
        assert!(matches!(&view.route, Route::Detail(item) if item.favorite && item.rating == 5 && item.comment == "Updated metadata"));
        full.name = "Stale result".into();
        view.receive_detail_metadata(generation.wrapping_sub(1), &request, Ok(full.clone()), cx);
        assert!(matches!(&view.route, Route::Detail(item) if item.name == "Full album 2"));
        view.route = Route::Settings;
        view.receive_detail_metadata(generation, &request, Ok(full.clone()), cx);
        assert_eq!(view.route, Route::Settings);
        view.route = Route::Detail(Box::new(full));
        view.album_details_scroll.scroll_to(gpui::ListOffset {item_ix:1, offset_in_item:gpui::px(0.)});
        cx.notify();
        assert_eq!(view.state.queue.entries[0].item.id, "preserved");
        assert_eq!(view.lyrics[0].text, "Preserved lyrics");
    }));
    cx.run_until_parked();
    let label = cx.debug_bounds("album-record-label-0").unwrap().center();
    cx.simulate_click(label, gpui::Modifiers::none());
    cx.run_until_parked();
    app.read_with(cx, |view, _| {
        assert_eq!(view.route, Route::Library(ItemKind::Album));
        assert_eq!(
            view.active_filters.custom.get("recordlabel"),
            Some(&json!(["Studio 42"]))
        );
        assert_eq!(
            view.state.settings.views[&format!("{}:library:album", server.id)]
                .filters
                .custom
                .get("recordlabel"),
            Some(&json!(["Studio 42"]))
        );
    });
    done.store(true, Ordering::Relaxed);
    fixture.join().unwrap();
    std::fs::remove_dir_all(dir).ok();
}

#[gpui::test]
fn native_theme_pipeline_preserves_accent_scale_contrast_and_original_css_color_aliases(
    cx: &mut TestAppContext,
) {
    use feishin_core::{appearance, styles::Target};
    use gpui::Rgba;
    use gpui_component::ActiveTheme;
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!("feishin-theme-color-ui-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        state.settings.follow_system_theme = false;
        state.settings.theme = "nord".into();
        state.settings.accent = "#dd7700".into();
        state.settings.use_theme_accent_color = false;
        state.settings.use_theme_primary_shade = false;
        state.settings.primary_shade = 0;
        state.settings.css.enabled = true;
        state.settings.css.content = "#native-root {background:var(--mantine-primary-color-filled);color:var(--theme-colors-primary-contrast);border-color:var(--theme-colors-dark-7)}".into();
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.run_until_parked();
    for (theme, shade) in [("nord", 0), ("defaultLight", 9)] {
        cx.update(|window, cx| {
            app.update(cx, |view, cx| {
                view.state.settings.theme = theme.into();
                view.state.settings.primary_shade = shade;
                view.apply_theme(window, cx);
                cx.notify();
            })
        });
        cx.run_until_parked();
        app.read_with(cx, |view, cx| {
            let palette = appearance::resolve(theme, &dir.join("Themes")).unwrap();
            let hsla = |[r, g, b, a]: [f32; 4]| gpui::Hsla::from(Rgba { r, g, b, a });
            let primary = hsla(appearance::primary(&palette, &view.state.settings).unwrap());
            let foreground =
                hsla(appearance::primary_contrast(&palette, &view.state.settings).unwrap());
            assert_eq!(cx.theme().primary, primary);
            assert_eq!(cx.theme().primary_foreground, foreground);
            let style = cx.global::<crate::styles::NativeStyles>().style(
                Target::new("body", "native-root", &[]),
                None,
                16.,
            );
            assert_eq!(style.background, Some(primary.into()));
            assert_eq!(style.text.as_ref().unwrap().color, Some(foreground));
            assert_eq!(
                style.border_color,
                Some(hsla(appearance::color("#181818").unwrap()))
            );
        });
    }
    std::fs::remove_dir_all(dir).ok();
}

#[gpui::test]
fn jukebox_output_mouse_selection_recovers_duplicate_entry_and_restores_local_volume(
    cx: &mut TestAppContext,
) {
    use feishin_core::{
        api::Api,
        model::{Server, ServerType, Session},
    };
    use gpui::Modifiers;
    use serde_json::json;
    use std::{
        io::{BufRead, BufReader, Write},
        net::TcpListener,
        sync::{
            Arc,
            atomic::{AtomicBool, Ordering},
        },
        thread,
        time::{Duration, Instant},
    };
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    listener.set_nonblocking(true).unwrap();
    let server = Server {
        id: uuid::Uuid::new_v4(),
        name: "Jukebox fixture".into(),
        url: format!("http://{}", listener.local_addr().unwrap()),
        username: "fixture".into(),
        kind: ServerType::Navidrome,
        legacy_auth: false,
        options: Default::default(),
    };
    let done = Arc::new(AtomicBool::new(false));
    let worker_done = done.clone();
    let worker = thread::spawn(move || {
        let deadline = Instant::now() + Duration::from_secs(30);
        while !worker_done.load(Ordering::SeqCst) && Instant::now() < deadline {
            let Ok((mut stream, _)) = listener.accept() else {
                thread::sleep(Duration::from_millis(5));
                continue;
            };
            stream.set_nonblocking(false).unwrap();
            stream
                .set_read_timeout(Some(Duration::from_secs(2)))
                .unwrap();
            let mut reader = BufReader::new(stream.try_clone().unwrap());
            let mut first = String::new();
            reader.read_line(&mut first).unwrap();
            loop {
                let mut line = String::new();
                reader.read_line(&mut line).unwrap();
                if line == "\r\n" || line.is_empty() {
                    break;
                }
            }
            let path = first.split_whitespace().nth(1).unwrap();
            let url = gpui::http_client::Url::parse(&format!("http://fixture{path}")).unwrap();
            let get = url
                .query_pairs()
                .any(|(name, value)| name == "action" && value == "get");
            let image = url.path().ends_with("getCoverArt.view");
            let body = if url.path().ends_with("jukeboxControl.view") && get {
                json!({"subsonic-response":{"status":"ok","jukeboxPlaylist":{"currentIndex":1,"playing":true,"position":7,"gain":0.23,"entry":[{"id":"duplicate","title":"First","duration":20},{"id":"duplicate","title":"Second","duration":20},{"id":"duplicate","title":"Third","duration":20}]}}}).to_string()
            } else {
                json!({"subsonic-response":{"status":"ok"}}).to_string()
            };
            let status = if image { "404 Not Found" } else { "200 OK" };
            write!(stream, "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}", body.len()).unwrap();
        }
    });
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!("feishin-jukebox-ui-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        state.settings.lyric_fetch = false;
        state.settings.scrobble = false;
        state.settings.volume = 40.;
        state.settings.mpv_path = dir.join("missing-mpv").to_string_lossy().into();
        state.queue.add(
            (0..3)
                .map(|index| Item {
                    id: "duplicate".into(),
                    name: format!("Duplicate {index}"),
                    server_id: server.id,
                    duration: 20.,
                    ..Default::default()
                })
                .collect(),
            Enqueue::Now,
        );
        state.queue.current = Some(state.queue.order[1]);
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.state.active_server = Some(server.id);
            view.sessions.insert(
                server.id,
                Api::new(server.clone(), Session::default()).unwrap(),
            );
            view.route = Route::Outputs;
            cx.notify();
        })
    });
    cx.run_until_parked();
    let output = cx.debug_bounds("jukebox-output").unwrap().center();
    cx.simulate_click(output, Modifiers::none());
    cx.run_until_parked();
    for _ in 0..200 {
        cx.update(|window, cx| app.update(cx, |view, cx| view.tick(window, cx)));
        cx.run_until_parked();
        if app.read_with(cx, |view, _| view.loaded && !view.buffering) {
            break;
        }
        thread::sleep(Duration::from_millis(10));
    }
    app.read_with(cx, |view, _| {
        assert!(
            view.state.settings.jukebox && view.loaded && view.playing,
            "{}",
            view.message
        );
        assert_eq!(view.jukebox_server, Some(server.id));
        assert_eq!(view.state.queue.current, Some(view.state.queue.order[1]));
        assert_eq!(view.state.queue.position, 7.);
        assert_eq!(view.state.settings.volume, 23.);
        assert_eq!(view.state.settings.previous_local_volume, Some(40.));
    });
    assert!(
        feishin_core::storage::load(&dir.join("state.json"))
            .unwrap()
            .settings
            .jukebox
    );
    let local = cx.debug_bounds("local-output").unwrap().center();
    cx.simulate_click(local, Modifiers::none());
    cx.run_until_parked();
    app.read_with(cx, |view, _| {
        assert!(!view.state.settings.jukebox);
        assert_eq!(view.jukebox_server, None);
        assert_eq!(view.state.settings.volume, 40.);
        assert_eq!(view.state.settings.previous_local_volume, None);
        assert_eq!(view.state.queue.current, Some(view.state.queue.order[1]));
    });
    // Only the deliberately missing MPV path can receive resumed local playback.
    cx.update(|_, cx| {
        app.update(cx, |view, _| {
            view.player.send(feishin_core::playback::Control::Stop);
        })
    });
    thread::sleep(Duration::from_millis(50));
    done.store(true, Ordering::SeqCst);
    worker.join().unwrap();
    std::fs::remove_dir_all(dir).ok();
}

#[gpui::test]
fn playlist_header_collapse_persists_and_plays_displayed_duplicates(cx: &mut TestAppContext) {
    use gpui::{Modifiers, MouseButton, px};
    use std::time::Duration;
    fn play_position(
        cx: &mut gpui::VisualTestContext,
        collapsed: bool,
    ) -> gpui::Point<gpui::Pixels> {
        if collapsed {
            let trigger = cx
                .debug_bounds("library-play-menu-trigger")
                .unwrap()
                .center();
            cx.simulate_click(trigger, Modifiers::none());
            cx.run_until_parked();
        }
        cx.debug_bounds(if collapsed {
            "play-visible"
        } else {
            "play-detail"
        })
        .unwrap()
        .center()
    }
    cx.set_assets(crate::icons::Assets);
    cx.update(gpui_component::init);
    let dir =
        std::env::temp_dir().join(format!("feishin-playlist-header-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.playlist_folders = true;
        state.settings.confirm_queue_changes = false;
        state.settings.mpv_path = dir.join("missing-mpv").to_string_lossy().into_owned();
        state.settings.play_button_behavior = feishin_core::queue::PlayBehavior::Last;
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.simulate_resize(gpui::size(px(1600.), px(1000.)));
    cx.run_until_parked();
    let songs = ["duplicate", "other", "duplicate"]
        .into_iter()
        .enumerate()
        .map(|(index, id)| Item {
            id: id.into(),
            name: format!("Song {index}"),
            album: "Album".into(),
            album_id: "album".into(),
            playlist_entry_id: format!("entry-{index}"),
            playlist_position: Some(index + 2),
            ..Default::default()
        })
        .collect::<Vec<_>>();
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.route = Route::Detail(Box::new(Item {
                id: "playlist".into(),
                name: "Folder/Displayed tracks".into(),
                comment: "Playlist notes at example.com\nMore information\nAnother line".into(),
                duration: 3672.,
                kind: ItemKind::Playlist,
                rules: Some("{}".into()),
                ..Default::default()
            }));
            view.items = songs.clone();
            view.total = Some(songs.len());
            view.loading = false;
            view.local_filter = "kept filter".into();
            view.selected.insert(1);
            cx.notify();
        })
    });
    cx.run_until_parked();
    let expanded = cx
        .debug_bounds("library-detail-header")
        .unwrap()
        .size
        .height;
    let before = app.read_with(cx, |view, _| {
        (
            view.route.clone(),
            view.history.clone(),
            view.selected.clone(),
            view.local_filter.clone(),
        )
    });
    let toggle = cx.debug_bounds("playlist-header-toggle").unwrap().center();
    cx.simulate_click(toggle, Modifiers::none());
    cx.run_until_parked();
    let compact = cx.debug_bounds("library-page-header").unwrap().size.height;
    assert!(compact < expanded / 2.);
    app.read_with(cx, |view, _| {
        assert!(view.state.settings.playlist_header_collapsed);
        assert_eq!(
            (
                view.route.clone(),
                view.history.clone(),
                view.selected.clone(),
                view.local_filter.clone()
            ),
            before
        );
    });
    assert!(
        feishin_core::storage::load(&dir.join("state.json"))
            .unwrap()
            .settings
            .playlist_header_collapsed
    );
    for albums in [false, true] {
        for collapsed in [true, false] {
            cx.update(|_, cx| {
                app.update(cx, |view, cx| {
                    view.state.settings.playlist_albums = albums;
                    view.items = if albums {
                        feishin_core::playlist_albums::rows(songs.clone())
                    } else {
                        songs.clone()
                    };
                    view.state.settings.playlist_header_collapsed = collapsed;
                    view.state.queue = Default::default();
                    view.state.queue.add(
                        vec![Item {
                            id: "old queue".into(),
                            ..Default::default()
                        }],
                        Enqueue::Now,
                    );
                    cx.notify();
                })
            });
            cx.run_until_parked();
            let play = play_position(cx, collapsed);
            cx.simulate_click(play, Modifiers::none());
            cx.run_until_parked();
            app.read_with(cx, |view, _| {
                let queued = view.state.queue.ordered();
                assert_eq!(
                    queued
                        .iter()
                        .map(|entry| entry.item.playlist_entry_id.as_str())
                        .collect::<Vec<_>>(),
                    ["entry-0", "entry-1", "entry-2"]
                );
                assert!(
                    queued
                        .iter()
                        .all(|entry| entry.item.context_playlist_id.as_deref() == Some("playlist"))
                );
                assert_eq!(
                    queued
                        .iter()
                        .map(|entry| entry.key)
                        .collect::<std::collections::HashSet<_>>()
                        .len(),
                    3
                );
                assert_eq!(
                    (
                        view.route.clone(),
                        view.history.clone(),
                        view.selected.clone(),
                        view.local_filter.clone()
                    ),
                    before
                );
            });
            let play = play_position(cx, collapsed);
            cx.simulate_mouse_down(play, MouseButton::Left, Modifiers::none());
            cx.executor().advance_clock(Duration::from_millis(500));
            cx.run_until_parked();
            let shuffled = app.read_with(cx, |view, _| {
                view.state
                    .queue
                    .entries
                    .iter()
                    .map(|entry| entry.key)
                    .collect::<Vec<_>>()
            });
            cx.simulate_mouse_up(play, MouseButton::Left, Modifiers::none());
            cx.run_until_parked();
            app.read_with(cx, |view, _| {
                assert_eq!(
                    view.state
                        .queue
                        .entries
                        .iter()
                        .map(|entry| entry.key)
                        .collect::<Vec<_>>(),
                    shuffled
                );
                let mut entries = view
                    .state
                    .queue
                    .entries
                    .iter()
                    .map(|entry| entry.item.playlist_entry_id.as_str())
                    .collect::<Vec<_>>();
                entries.sort();
                assert_eq!(entries, ["entry-0", "entry-1", "entry-2"]);
            });
        }
    }
    cx.simulate_resize(gpui::size(px(960.), px(640.)));
    for (selector, next) in [("play-detail-next", true), ("play-detail-last", false)] {
        for shuffle in [false, true] {
            cx.update(|_, cx| {
                app.update(cx, |view, cx| {
                    view.state.settings.playlist_header_collapsed = false;
                    view.state.queue = Default::default();
                    view.state.queue.add(
                        ["current", "tail"]
                            .into_iter()
                            .map(|id| Item {
                                id: id.into(),
                                ..Default::default()
                            })
                            .collect(),
                        Enqueue::Now,
                    );
                    view.state.queue.position = 17.;
                    cx.notify();
                })
            });
            cx.run_until_parked();
            let actions = cx.debug_bounds("library-detail-actions").unwrap();
            assert!(actions.right() <= px(960.));
            let viewport = app.read_with(cx, |view, _| view.album_details_scroll.viewport_bounds());
            let button = cx.debug_bounds(selector).unwrap().center();
            if !viewport.contains(&button) {
                cx.simulate_event(gpui::ScrollWheelEvent {
                    position: viewport.center(),
                    delta: gpui::ScrollDelta::Pixels(gpui::point(
                        px(0.),
                        viewport.center().y - button.y,
                    )),
                    modifiers: Modifiers::none(),
                    touch_phase: gpui::TouchPhase::Moved,
                });
                cx.run_until_parked();
            }
            let button = cx.debug_bounds(selector).unwrap().center();
            assert!(
                viewport.contains(&button),
                "{selector}: {button:?}, {viewport:?}"
            );
            if shuffle {
                cx.simulate_mouse_down(button, MouseButton::Left, Modifiers::none());
                cx.executor().advance_clock(Duration::from_millis(500));
                cx.run_until_parked();
                cx.simulate_mouse_up(button, MouseButton::Left, Modifiers::none());
            } else {
                cx.simulate_click(button, Modifiers::none());
            }
            cx.run_until_parked();
            app.read_with(cx, |view, _| {
                let queued = view.state.queue.ordered();
                assert_eq!(queued.len(), 5, "{selector}, shuffle={shuffle}");
                assert_eq!(queued[0].item.id, "current");
                assert_eq!(queued[if next { 4 } else { 1 }].item.id, "tail");
                assert_eq!(view.state.queue.position, 17.);
                let start = if next { 1 } else { 2 };
                let mut entries = queued[start..start + 3]
                    .iter()
                    .map(|entry| entry.item.playlist_entry_id.as_str())
                    .collect::<Vec<_>>();
                if shuffle {
                    entries.sort();
                }
                assert_eq!(entries, ["entry-0", "entry-1", "entry-2"]);
            });
        }
    }
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.items.clear();
            view.state.settings.playlist_header_collapsed = true;
            cx.notify();
        })
    });
    cx.run_until_parked();
    let queue = app.read_with(cx, |view, _| {
        serde_json::to_value(&view.state.queue).unwrap()
    });
    let play = play_position(cx, true);
    cx.simulate_click(play, Modifiers::none());
    cx.run_until_parked();
    app.read_with(cx, |view, _| {
        assert_eq!(serde_json::to_value(&view.state.queue).unwrap(), queue)
    });
    let toggle = cx.debug_bounds("playlist-header-toggle").unwrap().center();
    cx.simulate_click(toggle, Modifiers::none());
    cx.run_until_parked();
    assert!(
        !feishin_core::storage::load(&dir.join("state.json"))
            .unwrap()
            .settings
            .playlist_header_collapsed
    );
    drop(app);
    std::fs::remove_dir_all(dir).unwrap();
}

#[gpui::test]
fn artist_header_plays_ordered_discography_and_preserves_queue_on_failure(cx: &mut TestAppContext) {
    use feishin_core::{
        api::Api,
        filters::View,
        model::{Server, ServerType, Session, Sort},
    };
    use std::{
        io::{Read, Write},
        sync::{
            Arc, Mutex,
            atomic::{AtomicUsize, Ordering},
        },
        time::Duration,
    };
    cx.set_assets(crate::icons::Assets);
    cx.update(gpui_component::init);
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    listener.set_nonblocking(true).unwrap();
    let address = listener.local_addr().unwrap();
    let response_mode = Arc::new(AtomicUsize::new(0));
    let requests = Arc::new(Mutex::new(Vec::<String>::new()));
    let worker_mode = response_mode.clone();
    let worker_requests = requests.clone();
    let worker = std::thread::spawn(move || {
        let deadline = std::time::Instant::now() + Duration::from_secs(30);
        while worker_mode.load(Ordering::Relaxed) != 9 {
            assert!(
                std::time::Instant::now() < deadline,
                "Artist fixture timed out"
            );
            let Ok((mut stream, _)) = listener.accept() else {
                std::thread::sleep(Duration::from_millis(2));
                continue;
            };
            stream.set_nonblocking(false).unwrap();
            stream
                .set_read_timeout(Some(Duration::from_secs(2)))
                .unwrap();
            let mut bytes = [0; 8192];
            let length = stream.read(&mut bytes).unwrap();
            let request = String::from_utf8_lossy(&bytes[..length]);
            let url = gpui::http_client::Url::parse(&format!(
                "http://fixture{}",
                request.split_whitespace().nth(1).unwrap()
            ))
            .unwrap();
            let id = url
                .query_pairs()
                .find(|(key, _)| key == "id")
                .map(|(_, value)| value.into_owned())
                .unwrap_or_default();
            let mut status = "200 OK";
            let body = if url.path() == "/rest/getArtist.view" {
                worker_requests.lock().unwrap().push("artist".into());
                while worker_mode.load(Ordering::Relaxed) == 3 {
                    assert!(std::time::Instant::now() < deadline);
                    std::thread::sleep(Duration::from_millis(2));
                }
                let albums = if worker_mode.load(Ordering::Relaxed) == 1 {
                    serde_json::json!([])
                } else {
                    serde_json::json!([
                        {"id":"old","name":"A old","artistId":"artist","year":2000,"releaseTypes":["album"]},
                        {"id":"ep","name":"Hidden EP","artistId":"artist","year":2025,"releaseTypes":["ep"]},
                        {"id":"appears","name":"Guest album","artistId":"other","year":2026,"releaseTypes":["album"]},
                        {"id":"new","name":"Z new","artistId":"artist","year":2024,"releaseTypes":["album"]}
                    ])
                };
                serde_json::json!({"subsonic-response":{"status":"ok","artist":{"album":albums}}})
            } else if url.path() == "/rest/getAlbum.view" {
                worker_requests.lock().unwrap().push(id.clone());
                assert_ne!(id, "ep", "Disabled release groups must not be fetched");
                if worker_mode.load(Ordering::Relaxed) == 2 && id == "old" {
                    status = "500 Internal Server Error";
                }
                let songs = if id == "new" {
                    serde_json::json!([
                        {"id":"new-performer","title":"New performer","artistId":"artist"},
                        {"id":"new-album-artist","title":"New album artist","artistId":"other","albumArtists":[{"id":"artist","name":"Artist"}]},
                        {"id":"new-remixer","title":"New remix","artistId":"other","contributors":[{"role":"remixer","artist":{"id":"artist","name":"Artist"}}]},
                        {"id":"unrelated","title":"Unrelated","artistId":"other"}
                    ])
                } else {
                    serde_json::json!([{"id":id,"title":id,"artistId":"artist"}])
                };
                serde_json::json!({"subsonic-response":{"status":"ok","album":{"song":songs}}})
            } else {
                serde_json::json!({"subsonic-response":{"status":"ok"}})
            }.to_string();
            write!(stream, "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}", body.len()).ok();
        }
    });
    let dir = std::env::temp_dir().join(format!("feishin-artist-header-{}", uuid::Uuid::new_v4()));
    let server = uuid::Uuid::new_v4();
    let artist = Item {
        id: "artist".into(),
        name: "Artist".into(),
        server_id: server,
        kind: ItemKind::AlbumArtist,
        ..Default::default()
    };
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        state.settings.lyric_fetch = false;
        state.settings.confirm_queue_changes = false;
        state.settings.mpv_path = dir.join("missing-mpv").to_string_lossy().into_owned();
        state.settings.artist_release_types = ["album", "appears-on", "ep"]
            .into_iter()
            .map(|id| feishin_core::releases::Setting {
                id: id.into(),
                disabled: id == "ep",
            })
            .collect();
        let app = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        app.update(cx, |view, _| {
            view.route = Route::Detail(Box::new(artist.clone()));
            view.artist_overview = false;
            view.artist_tab = ArtistTab::Albums;
            view.restore_view();
            assert_eq!((view.sort, view.descending), (Sort::ReleaseDate, true));
            view.loading = false;
            view.sessions.insert(
                server,
                Api::new(
                    Server {
                        id: server,
                        name: "Fixture".into(),
                        url: format!("http://{address}"),
                        kind: ServerType::Subsonic,
                        username: "fixture".into(),
                        legacy_auth: false,
                        options: Default::default(),
                    },
                    Session::default(),
                )
                .unwrap(),
            );
        });
        captured.replace(Some(app.clone()));
        Root::new(app, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.simulate_resize(gpui::size(gpui::px(1600.), gpui::px(1000.)));
    for (case, tab, sort, descending, expected) in [
        (
            0,
            ArtistTab::Albums,
            Sort::ReleaseDate,
            true,
            vec![
                "new-performer",
                "new-album-artist",
                "new-remixer",
                "old",
                "appears",
            ],
        ),
        (
            0,
            ArtistTab::Songs,
            Sort::Name,
            false,
            vec![
                "old",
                "new-performer",
                "new-album-artist",
                "new-remixer",
                "appears",
            ],
        ),
        (
            0,
            ArtistTab::Favorites,
            Sort::ReleaseDate,
            true,
            vec![
                "new-performer",
                "new-album-artist",
                "new-remixer",
                "old",
                "appears",
            ],
        ),
        (1, ArtistTab::Albums, Sort::ReleaseDate, true, vec![]),
        (2, ArtistTab::Albums, Sort::ReleaseDate, true, vec![]),
        (3, ArtistTab::Albums, Sort::ReleaseDate, true, vec![]),
    ] {
        response_mode.store(case, Ordering::Relaxed);
        requests.lock().unwrap().clear();
        cx.update(|_, cx| {
            app.update(cx, |view, cx| {
                view.route = Route::Detail(Box::new(artist.clone()));
                view.artist_tab = tab;
                view.sort = sort;
                view.descending = descending;
                view.state.settings.views.insert(
                    format!("{server}:detail:albumArtistAlbum"),
                    View {
                        sort,
                        descending,
                        ..Default::default()
                    },
                );
                // The current song tab, local filter and selection must not constrain header playback.
                if tab != ArtistTab::Albums {
                    view.sort = Sort::Random;
                }
                view.items = vec![Item {
                    id: "unrelated selection".into(),
                    ..Default::default()
                }];
                view.selected = [0].into_iter().collect();
                view.local_filter = "unmatched filter".into();
                view.state.queue = Default::default();
                view.state.queue.add(
                    ["current", "tail"]
                        .into_iter()
                        .map(|id| Item {
                            id: id.into(),
                            ..Default::default()
                        })
                        .collect(),
                    Enqueue::Now,
                );
                view.state.queue.position = 17.;
                view.message.clear();
                view.play_detail(Enqueue::Next, false, cx);
            })
        });
        if case == 3 {
            cx.update(|_, cx| {
                app.update(cx, |view, _| {
                    for cancelled in view.library_fetches.values() {
                        cancelled.store(true, Ordering::Relaxed);
                    }
                })
            });
            response_mode.store(0, Ordering::Relaxed);
        }
        for _ in 0..400 {
            cx.run_until_parked();
            if app.read_with(cx, |view, _| view.library_fetches.is_empty()) {
                break;
            }
            std::thread::sleep(Duration::from_millis(5));
        }
        app.read_with(cx, |view, _| {
            assert!(view.library_fetches.is_empty());
            let queued = view.state.queue.ordered();
            let ids = queued
                .iter()
                .map(|entry| entry.item.id.as_str())
                .collect::<Vec<_>>();
            let mut all_expected = vec!["current"];
            all_expected.extend(expected);
            all_expected.push("tail");
            assert_eq!(
                ids, all_expected,
                "case {case}, tab {tab:?}: {}",
                view.message
            );
            assert!(
                queued
                    .iter()
                    .all(|entry| entry.item.context_playlist_id.is_none())
            );
            assert_eq!(view.state.queue.position, 17.);
            assert_eq!(view.selected, std::collections::HashSet::from([0]));
            assert_eq!(view.local_filter, "unmatched filter");
            assert_eq!(view.route, Route::Detail(Box::new(artist.clone())));
            if case == 2 {
                assert!(!view.message.is_empty());
            }
        });
        if case == 0 {
            let calls = requests.lock().unwrap();
            assert_eq!(
                *calls,
                if sort == Sort::Name {
                    vec!["artist", "old", "new", "appears"]
                } else {
                    vec!["artist", "new", "old", "appears"]
                }
            );
        }
    }
    response_mode.store(9, Ordering::Relaxed);
    worker.join().unwrap();
    drop(app);
    std::fs::remove_dir_all(dir).ok();
}

#[gpui::test]
fn playlist_album_mouse_play_and_selection_keep_group_tracks_and_entry_positions(
    cx: &mut TestAppContext,
) {
    use feishin_core::{
        api::Api,
        model::{Server, ServerType, Session},
        queue::PlayBehavior,
    };
    use gpui::Modifiers;
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!(
        "feishin-playlist-albums-ui-{}",
        uuid::Uuid::new_v4()
    ));
    let server = uuid::Uuid::new_v4();
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        state.settings.mpv_path = dir.join("missing-mpv").to_string_lossy().into_owned();
        state.settings.play_button_behavior = PlayBehavior::Next;
        state.settings.confirm_queue_changes = false;
        state.settings.playlist_albums = true;
        state.queue.add(
            vec![Item {
                id: "old".into(),
                server_id: server,
                ..Default::default()
            }],
            Enqueue::Now,
        );
        state.queue.position = 7.;
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.simulate_resize(gpui::size(gpui::px(1400.), gpui::px(1200.)));
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.sessions.insert(
                server,
                Api::new(
                    Server {
                        id: server,
                        name: "Fixture".into(),
                        url: "http://127.0.0.1:1".into(),
                        username: "fixture".into(),
                        kind: ServerType::Navidrome,
                        legacy_auth: false,
                        options: Default::default(),
                    },
                    Session::default(),
                )
                .unwrap(),
            );
            view.route = Route::Detail(Box::new(Item {
                id: "playlist".into(),
                name: "Playlist".into(),
                server_id: server,
                kind: ItemKind::Playlist,
                ..Default::default()
            }));
            let songs = ["a", "a", "b", "a"]
                .into_iter()
                .enumerate()
                .map(|(i, album)| Item {
                    id: if i == 1 { "s0".into() } else { format!("s{i}") },
                    name: format!("Song {i}"),
                    album: format!("Album {album}"),
                    album_id: album.into(),
                    server_id: server,
                    track: if i == 0 { 3 } else { 1 },
                    playlist_position: Some(i),
                    playlist_entry_id: format!("entry{i}"),
                    ..Default::default()
                })
                .collect();
            view.items = feishin_core::playlist_albums::rows(songs);
            view.total = Some(3);
            view.loading = false;
            assert_eq!(view.list_key(), "playlistAlbum");
            view.selected.extend([0, 2]);
            let selected = view.selected_library_items();
            assert_eq!(
                selected
                    .iter()
                    .map(|song| song.playlist_position.unwrap())
                    .collect::<Vec<_>>(),
                [0, 1, 3]
            );
            let drag = view.drag_library_item(0);
            assert_eq!(drag.items, selected);
            assert_eq!(
                drag.playlist_source
                    .unwrap()
                    .entries
                    .iter()
                    .map(|entry| entry.0)
                    .collect::<Vec<_>>(),
                [0, 2]
            );
            assert_ne!(
                Feishin::album_key(&view.items[0]),
                Feishin::album_key(&view.items[2])
            );
            assert_eq!(view.playlist_index(2), 3);
            view.selected.clear();
            cx.notify();
        })
    });
    cx.run_until_parked();
    show_card_controls(cx, 0);
    let play = cx.debug_bounds("library-play-0").unwrap();
    cx.simulate_click(play.center(), Modifiers::default());
    cx.run_until_parked();
    app.read_with(cx, |view, _| {
        assert_eq!(
            view.state
                .queue
                .entries
                .iter()
                .map(|entry| entry.item.id.as_str())
                .collect::<Vec<_>>(),
            ["s0", "s0"],
            "Play bounds {play:?}: {}",
            view.message
        );
        assert_eq!(
            view.state
                .queue
                .entries
                .iter()
                .map(|entry| entry.item.playlist_position.unwrap())
                .collect::<Vec<_>>(),
            [1, 0]
        );
        assert_eq!(view.state.queue.position, 0.);
    });
    let toggle = cx.debug_bounds("playlist-target").unwrap();
    cx.simulate_click(toggle.center(), Modifiers::default());
    cx.run_until_parked();
    assert!(!app.read_with(cx, |view, _| view.state.settings.playlist_albums));
    assert!(
        !feishin_core::storage::load(&dir.join("state.json"))
            .unwrap()
            .settings
            .playlist_albums
    );
    std::fs::remove_dir_all(dir).unwrap();
}

#[gpui::test]
fn artwork_preferences_placeholders_and_cache_refresh_work_headlessly(cx: &mut TestAppContext) {
    use feishin_core::images::{Placeholder, Placement};
    use gpui::Modifiers;
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!("feishin-images-ui-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            view.route = Route::Settings;
            view.settings_search.update(cx, |input, cx| {
                input.set_value("cover art aspect", window, cx)
            });
            cx.notify();
        })
    });
    cx.run_until_parked();
    let aspect = cx.debug_bounds("native-image-aspect").unwrap();
    cx.simulate_click(aspect.center(), Modifiers::default());
    assert!(app.read_with(cx, |view, _| view.state.settings.native_image_aspect_ratio));
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            for (input, size) in view
                .image_resolution_inputs
                .iter()
                .zip([0, 700, 500, 400, 90])
            {
                input.update(cx, |input, cx| {
                    input.set_value(size.to_string(), window, cx)
                });
            }
            for index in 0..5 {
                view.apply_image_resolution(index, cx);
            }
            assert_eq!(view.state.settings.image_resolution.header, 700.);
            assert_eq!(view.state.settings.image_resolution.table, 90.);
            view.image_resolution_inputs[4]
                .update(cx, |input, cx| input.set_value("NaN", window, cx));
            view.apply_image_resolution(4, cx);
            assert_eq!(view.state.settings.image_resolution.table, 90.);
            let item = Item {
                id: "album".into(),
                kind: ItemKind::Album,
                blur_hash: "LEHV6nWB2yk8pyo0adR*.7kCMdnj".into(),
                cover_id: "art".into(),
                ..Default::default()
            };
            view.state.settings.image_placeholder = Placeholder::Blurhash;
            view.route = Route::Detail(Box::new(item.clone()));
            view.items.clear();
            let base = Feishin::cover_key(&item);
            let table = view.cover_cache_key(&item, Placement::Table);
            let header = view.cover_cache_key(&item, Placement::Header);
            let covers = dir.join("covers");
            std::fs::create_dir_all(&covers).unwrap();
            for key in [&base, &table, &header] {
                let path = covers.join(format!("{key}.img"));
                std::fs::write(&path, b"old cached image").unwrap();
                view.covers.insert(key.clone(), path);
            }
            view.invalidate_artwork(&base, false);
            assert!(view.covers.is_empty());
            assert_ne!(view.cover_cache_key(&item, Placement::Header), header);
            assert!(!covers.join(format!("{header}.img")).exists());
            view.fetch_covers(cx);
            cx.notify();
        })
    });
    cx.run_until_parked();
    assert!(cx.debug_bounds("artwork-placeholder").is_some());
    let saved = feishin_core::storage::load(&dir.join("state.json")).unwrap();
    assert_eq!(saved.settings.image_resolution.header, 700.);
    assert_eq!(saved.settings.image_resolution.table, 90.);
    assert!(saved.settings.native_image_aspect_ratio);
    std::fs::remove_dir_all(dir).unwrap();
}

#[gpui::test]
fn artist_overview_order_search_and_mouse_play_preserve_section_context(cx: &mut TestAppContext) {
    use crate::artist_overview::Section;
    use feishin_core::{
        api::Api,
        model::{Server, ServerType, Session},
        queue::PlayBehavior,
    };
    use gpui::{Modifiers, MouseButton};
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!(
        "feishin-artist-overview-ui-{}",
        uuid::Uuid::new_v4()
    ));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        state.settings.play_button_behavior = PlayBehavior::Next;
        state.settings.artist_items = vec![
            feishin_core::releases::Setting {
                id: "topSongs".into(),
                disabled: false,
            },
            feishin_core::releases::Setting {
                id: "biography".into(),
                disabled: false,
            },
            feishin_core::releases::Setting {
                id: "similarArtists".into(),
                disabled: false,
            },
        ];
        state.queue.add(
            vec![Item {
                id: "old".into(),
                ..Default::default()
            }],
            Enqueue::Now,
        );
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.simulate_resize(gpui::size(gpui::px(1600.), gpui::px(1400.)));
    cx.run_until_parked();
    let server = uuid::Uuid::new_v4();
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.sessions.insert(
                server,
                Api::new(
                    Server {
                        id: server,
                        name: "Fixture".into(),
                        url: "http://127.0.0.1:1".into(),
                        username: "fixture".into(),
                        kind: ServerType::Navidrome,
                        legacy_auth: false,
                        options: Default::default(),
                    },
                    Session::default(),
                )
                .unwrap(),
            );
            view.route = Route::Detail(Box::new(Item {
                id: "artist".into(),
                name: "Artist".into(),
                kind: ItemKind::AlbumArtist,
                server_id: server,
                ..Default::default()
            }));
            view.artist_info = Some(ArtistInfo {
                biography: "Biography".into(),
                ..Default::default()
            });
            view.artist_sections.insert(
                "topSongs".into(),
                Section {
                    items: ["First", "Second", "Third"]
                        .into_iter()
                        .enumerate()
                        .map(|(index, name)| Item {
                            id: index.to_string(),
                            name: name.into(),
                            server_id: server,
                            ..Default::default()
                        })
                        .collect(),
                    ..Default::default()
                },
            );
            view.artist_sections.insert(
                "similarArtists".into(),
                Section {
                    items: vec![Item {
                        kind: ItemKind::AlbumArtist,
                        id: "related".into(),
                        name: "Related".into(),
                        server_id: server,
                        ..Default::default()
                    }],
                    ..Default::default()
                },
            );
            cx.notify();
        })
    });
    cx.run_until_parked();
    let top = cx.debug_bounds("artist-overview-topSongs").unwrap();
    let bio = cx.debug_bounds("artist-overview-biography").unwrap();
    assert!(bio.origin.y > top.origin.y);
    let similar_before = cx.debug_bounds("artist-overview-similarArtists").unwrap();
    let row = cx
        .debug_bounds("artist-cell-topSongs-1-titleCombined")
        .unwrap();
    cx.simulate_mouse_down(row.center(), MouseButton::Left, Modifiers::none());
    cx.simulate_mouse_up(row.center(), MouseButton::Left, Modifiers::none());
    cx.run_until_parked();
    app.read_with(cx, |view, _| {
        assert_eq!(view.state.queue.entries.len(), 1);
        assert_eq!(
            view.artist_sections["topSongs"].selected,
            std::collections::HashSet::from(["1".into()])
        );
    });
    let next = cx
        .debug_bounds("artist-section-play-topSongs-next")
        .unwrap()
        .center();
    cx.simulate_click(next, Modifiers::none());
    cx.run_until_parked();
    assert_eq!(
        app.read_with(cx, |view, _| view
            .state
            .queue
            .ordered()
            .iter()
            .map(|entry| entry.item.id.clone())
            .collect::<Vec<_>>()),
        ["old", "0", "1", "2"]
    );
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.state.settings.artist_items[1].disabled = true;
            view.save();
            cx.notify();
        })
    });
    cx.refresh().unwrap();
    cx.run_until_parked();
    assert!(app.read_with(cx, |view, _| view.state.settings.artist_items[1].disabled));
    // GPUI 0.2.2 retains old debug selectors in recycled frame maps. Measure a
    // surviving section instead of treating a historic bound as a live element.
    let similar_after = cx.debug_bounds("artist-overview-similarArtists").unwrap();
    assert!(similar_after.origin.y < similar_before.origin.y);
    let top_before = cx.debug_bounds("artist-overview-topSongs").unwrap();
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            view.artist_searches[0].update(cx, |input, cx| input.set_value("Second", window, cx));
            cx.notify();
        })
    });
    cx.refresh().unwrap();
    cx.run_until_parked();
    assert_eq!(
        app.read_with(cx, |view, cx| view.artist_section_indices("topSongs", cx)),
        [0, 1, 2]
    );
    cx.executor()
        .advance_clock(std::time::Duration::from_millis(299));
    cx.run_until_parked();
    assert_eq!(
        app.read_with(cx, |view, cx| view.artist_section_indices("topSongs", cx)),
        [0, 1, 2]
    );
    cx.executor()
        .advance_clock(std::time::Duration::from_millis(1));
    cx.run_until_parked();
    assert_eq!(
        app.read_with(cx, |view, cx| view.artist_section_indices("topSongs", cx)),
        [1]
    );
    let top_after = cx.debug_bounds("artist-overview-topSongs").unwrap();
    assert!(top_after.size.height < top_before.size.height);
    assert!(cx.debug_bounds("artist-section-song-topSongs-1").is_some());
    let saved = feishin_core::storage::load(&dir.join("state.json")).unwrap();
    assert_eq!(saved.settings.artist_items[0].id, "topSongs");
    assert!(saved.settings.artist_items[1].disabled);
    std::fs::remove_dir_all(dir).ok();
}

#[gpui::test]
fn grouped_song_artwork_plays_the_list_context_with_duplicate_tracks(cx: &mut TestAppContext) {
    use feishin_core::{
        api::Api,
        model::{Server, ServerType, Session},
        queue::PlayBehavior,
    };
    use gpui::{Modifiers, MouseButton};
    cx.update(gpui_component::init);
    let dir =
        std::env::temp_dir().join(format!("feishin-grouped-songs-ui-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        state.settings.scrobble = false;
        state.settings.lyric_fetch = false;
        state.settings.mpv_path = dir.join("missing-mpv-fixture").to_string_lossy().into();
        state.settings.play_button_behavior = PlayBehavior::Next;
        state.settings.album_group.image_size = 80.;
        state.settings.album_group.items = vec![
            feishin_core::releases::Setting {
                id: "songCount".into(),
                disabled: false,
            },
            feishin_core::releases::Setting {
                id: "duration".into(),
                disabled: false,
            },
        ];
        let mut config = feishin_core::lists::default_for("song");
        config.table.size = feishin_core::lists::Size::Compact;
        config
            .table
            .columns
            .iter_mut()
            .find(|column| column.id == "albumGroup")
            .unwrap()
            .is_enabled = true;
        state.settings.lists.insert("song".into(), config);
        state.queue.add(
            vec![Item {
                id: "old".into(),
                ..Default::default()
            }],
            Enqueue::Now,
        );
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    let server = uuid::Uuid::new_v4();
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.sessions.insert(
                server,
                Api::new(
                    Server {
                        id: server,
                        name: "Fixture".into(),
                        url: "http://127.0.0.1:1".into(),
                        username: "fixture".into(),
                        kind: ServerType::Navidrome,
                        legacy_auth: false,
                        options: Default::default(),
                    },
                    Session::default(),
                )
                .unwrap(),
            );
            view.route = Route::Library(ItemKind::Song);
            view.items = (0..6)
                .map(|index| Item {
                    id: if index == 1 {
                        "0".into()
                    } else {
                        index.to_string()
                    },
                    name: format!("Song {index}"),
                    server_id: server,
                    album: if index < 4 { "A" } else { "B" }.into(),
                    album_id: if index < 4 { "a" } else { "b" }.into(),
                    duration: 15.,
                    playlist_position: Some(index),
                    ..Default::default()
                })
                .collect();
            for (id, name) in [("a", "A"), ("b", "B")] {
                let album = Item {
                    id: id.into(),
                    name: name.into(),
                    server_id: server,
                    kind: ItemKind::Album,
                    favorite: true,
                    rating: 4,
                    ..Default::default()
                };
                view.album_metadata_cache
                    .insert(Feishin::album_key(&album), Some(album));
            }
            assert!(view.grouped_song_albums());
            assert!(
                view.configured_columns()
                    .iter()
                    .all(|column| column.id != "albumGroup")
            );
            cx.notify();
        })
    });
    cx.run_until_parked();
    let count = cx.debug_bounds("album-group-0-songCount").unwrap();
    let duration = cx.debug_bounds("album-group-0-duration").unwrap();
    assert!(duration.origin.y > count.origin.y);
    let play = cx.debug_bounds("album-group-play-0").unwrap();
    assert_eq!(f32::from(play.size.width), 80.);
    let current = app.read_with(cx, |view, _| view.state.queue.current);
    cx.simulate_mouse_down(play.center(), MouseButton::Left, Modifiers::none());
    cx.simulate_mouse_up(play.center(), MouseButton::Left, Modifiers::none());
    cx.run_until_parked();
    app.read_with(cx, |view, _| {
        assert_eq!(view.state.queue.current, current);
        assert_eq!(
            view.state
                .queue
                .ordered()
                .iter()
                .map(|entry| entry.item.id.as_str())
                .collect::<Vec<_>>(),
            ["old", "0"]
        );
        assert_eq!(
            view.state
                .queue
                .entries
                .iter()
                .filter(|entry| entry.item.id == "0")
                .count(),
            1
        );
    });
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            view.state.settings.play_button_behavior = PlayBehavior::Now;
            view.state.settings.confirm_queue_changes = false;
            cx.notify();
        })
    });
    cx.simulate_click(play.center(), Modifiers::none());
    cx.run_until_parked();
    app.read_with(cx, |view, _| {
        assert_eq!(
            view.state
                .queue
                .ordered()
                .iter()
                .map(|entry| entry.item.id.as_str())
                .collect::<Vec<_>>(),
            ["0", "0", "0", "2", "3", "4", "5"]
        );
        assert_eq!(view.state.queue.up_next, [view.state.queue.order[1]]);
        assert_eq!(
            view.state.queue.current().unwrap().item.playlist_position,
            Some(0)
        );
    });
    cx.update(|_, cx| {
        app.update(cx, |view, cx| {
            let mut album = view.album_metadata_cache[&format!("{server}:a")]
                .clone()
                .unwrap();
            album.favorite = false;
            album.rating = 2;
            view.update_library_item(&album);
            assert_eq!(
                view.album_metadata_cache[&Feishin::album_key(&album)]
                    .as_ref()
                    .unwrap()
                    .rating,
                2
            );
            view.state.settings.album_group.vertical_layout = false;
            view.save();
            cx.notify();
        })
    });
    let saved = feishin_core::storage::load(&dir.join("state.json")).unwrap();
    assert_eq!(saved.settings.album_group.image_size, 80.);
    assert!(!saved.settings.album_group.vertical_layout);
    std::fs::remove_dir_all(dir).ok();
}

#[gpui::test]
fn typed_share_expiration_rejects_invalid_amounts_and_persists_units(cx: &mut TestAppContext) {
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!("feishin-share-ui-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            view.open_share(
                vec![Item {
                    id: "fixture".into(),
                    ..Default::default()
                }],
                window,
                cx,
            );
            assert_eq!(
                view.state.settings.share_expiration.as_ref().unwrap().unit,
                feishin_core::sharing::Unit::Year
            );
            assert!(!view.share_expiry.read(cx).value().is_empty());
            view.share_amount
                .update(cx, |input, cx| input.set_value("2", window, cx));
            view.apply_share_expiration(Some(feishin_core::sharing::Unit::Month), None, window, cx);
            let expected = view.state.settings.share_expiration.clone();
            view.share_amount
                .update(cx, |input, cx| input.set_value("0", window, cx));
            view.apply_share_expiration(None, None, window, cx);
            assert_eq!(view.state.settings.share_expiration, expected);
            view.share_amount
                .update(cx, |input, cx| input.set_value("2", window, cx));
            view.apply_share_expiration(None, Some(true), window, cx);
            assert!(view.share_expiry.read(cx).value().is_empty());
        })
    });
    let saved = feishin_core::storage::load(&dir.join("state.json")).unwrap();
    let expiration = saved.settings.share_expiration.unwrap();
    assert_eq!(expiration.amount, 2);
    assert_eq!(expiration.unit, feishin_core::sharing::Unit::Month);
    assert!(expiration.use_server_default);
    std::fs::remove_dir_all(dir).ok();
}

#[gpui::test]
fn musical_speed_controls_clamp_and_persist_without_audio(cx: &mut TestAppContext) {
    cx.update(gpui_component::init);
    let dir = std::env::temp_dir().join(format!("feishin-pitch-ui-{}", uuid::Uuid::new_v4()));
    let captured = Rc::new(RefCell::new(None));
    let (_, cx) = cx.add_window_view(|window, cx| {
        let mut state = fixture_state();
        state.settings.home.feature = false;
        state.settings.home.items.clear();
        let view = cx.new(|cx| Feishin::new(dir.clone(), Ok(state), window, cx));
        captured.replace(Some(view.clone()));
        Root::new(view, window, cx)
    });
    let app = captured.borrow_mut().take().unwrap();
    cx.update(|window, cx| {
        app.update(cx, |view, cx| {
            view.adjust_musical_speed(1., window, cx);
            assert!((view.state.settings.speed - 2_f32.powf(1. / 12.)).abs() < 1e-6);
            view.adjust_musical_speed(-1., window, cx);
            assert!((view.state.settings.speed - 1.).abs() < 1e-6);
            view.state.settings.microtonal_pitch_controls = true;
            view.adjust_musical_speed(0.1, window, cx);
            assert!((view.state.settings.speed - 2_f32.powf(0.1 / 12.)).abs() < 1e-6);
            view.set_playback_speed(f32::NAN, window, cx);
            assert!(view.state.settings.speed.is_finite());
            view.set_playback_speed(0.01, window, cx);
            assert_eq!(view.state.settings.speed, 0.5);
            view.adjust_musical_speed(-1., window, cx);
            assert_eq!(view.state.settings.speed, 0.5);
            view.set_playback_speed(4., window, cx);
            view.adjust_musical_speed(0.1, window, cx);
            assert_eq!(view.state.settings.speed, 2.);
            assert_eq!(view.speed_input.read(cx).value(), "2");
        })
    });
    let saved = feishin_core::storage::load(&dir.join("state.json")).unwrap();
    assert_eq!(saved.settings.speed, 2.);
    assert!(saved.settings.microtonal_pitch_controls);
    std::fs::remove_dir_all(dir).ok();
}

